-- What the Security+ Exam Actually Tests
update lessons set content_blocks = '[{"text": "What the Security+ Exam Actually Tests", "type": "title", "overview": "A map of the five domains covered in this course, and how CompTIA actually scores the SY0-701 exam.", "examContext": "Why this matters: domain weights tell you where to put your study time before you spend a single hour on content."}, {"type": "term_set", "heading": "The exam at a glance", "terms": [{"term": "Exam", "short": "CompTIA Security+ SY0-701."}, {"term": "Length", "short": "Up to 90 questions in 90 minutes."}, {"term": "Question types", "short": "Multiple choice plus performance-based questions (PBQs)."}, {"term": "Passing score", "short": "750 on a 100 to 900 scale."}]}, {"type": "compare", "heading": "The five domains and their weight", "columns": ["Weight"], "rows": [{"label": "1. General Security Concepts", "values": ["12%"]}, {"label": "2. Threats, Vulnerabilities, and Mitigations", "values": ["22%"]}, {"label": "3. Security Architecture", "values": ["18%"]}, {"label": "4. Security Operations", "values": ["28%, the largest"]}, {"label": "5. Security Program Management and Oversight", "values": ["20%"]}]}, {"type": "key_term", "term": "Performance-based question (PBQ)", "definition": "An interactive task, such as a drag-and-drop, a simulated firewall configuration or a log to interpret, that tests whether you can do something rather than recognize a term.", "example": "You''re shown a firewall rule table and asked to reorder the rules so web traffic is allowed and everything else is denied."}, {"type": "callout", "variant": "tip", "text": "Security Operations, Threats and Vulnerabilities, and Program Management together make up 70% of your score. Let your study time follow the weights."}]'::jsonb where id = 'b6695541-0b6f-4313-883c-35db92af4acb';

-- How to Use Orivian
update lessons set content_blocks = '[{"text": "How to Use Orivian", "type": "title", "overview": "How a domain''s lessons, recap, and checkpoint fit together, and what it takes to mark a lesson complete.", "examContext": "Why this matters: understanding the platform''s rhythm up front means you spend your time studying, not figuring out the interface."}, {"type": "paragraph", "text": "Every domain in this course follows the same pattern. Learn it once and you know it everywhere."}, {"type": "diagram", "heading": "Inside a domain", "diagram": {"kind": "flow", "steps": [{"label": "Lessons", "note": "Each lesson ends in a 10-question mini-exam. 80% to pass; retake as often as you like."}, {"label": "Domain recap", "note": "The highest-yield facts from every lesson, plus rapid practice questions. No exam."}, {"label": "Domain checkpoint", "note": "A longer exam across the whole domain, with fresh scenarios. The real test of whether it stuck."}]}}, {"type": "term_set", "heading": "How a lesson is laid out", "terms": [{"term": "Key terms at a glance", "short": "Every term with a one-line definition, often next to a diagram."}, {"term": "Breakdown", "short": "Terms in depth, each with an \"In practice\" example."}, {"term": "Side by side", "short": "Comparison tables for the pairs the exam loves, with an exam cue row."}, {"term": "How this shows up on the exam", "short": "Practice questions: pick an answer, then see why it''s right and what the trap was. Not scored."}, {"term": "Mini-exam", "short": "The graded questions at the end. You can review every past attempt afterwards."}]}, {"type": "term_set", "heading": "Finding your way", "terms": [{"term": "The trail map", "short": "Each course page shows your path as a trail: covered ground in green, your next waypoint in gold."}, {"term": "Next waypoint", "short": "The card at the top of the course page always points to your next step."}, {"term": "Study timer", "short": "Counts only while a lesson or exam is visible in front of you. For your awareness; never graded."}, {"term": "Listen", "short": "Any slide can be read aloud. Turn on auto-play in Voice settings to hear each slide as you press Next."}, {"term": "Keyboard", "short": "Arrow keys move between slides, L listens, N opens notes."}]}, {"type": "term_set", "heading": "Your notes", "terms": [{"term": "Write a note", "short": "Open Notes in any lesson and type; it''s linked to that lesson automatically."}, {"term": "Save to notes", "short": "Select any sentence in a lesson and tap Save to notes to keep it as a quote."}, {"term": "My Notes", "short": "Everything you''ve saved, on the Notes page, grouped by course and lesson."}], "intro": "Notes are private to you and follow your account to any device."}, {"type": "callout", "variant": "tip", "text": "One or two lessons done attentively beat a skimmed marathon. Use the recap right before the checkpoint."}]'::jsonb where id = 'b648dcf9-7ca8-463b-92d7-54c833139502';

-- A Study Strategy That Works
update lessons set content_blocks = '[{"text": "A Study Strategy That Works", "type": "title", "overview": "A short, practical approach to pacing your study time and retaining what you read.", "examContext": "Why this matters: how you study affects retention as much as what you study, especially for a scenario-heavy exam like Security+."}, {"type": "paragraph", "text": "The most common Security+ study mistake is spending equal time on every domain. Security Operations (28%) and Threats and Vulnerabilities (22%) make up half the exam, so they deserve about half your time."}, {"type": "term_set", "heading": "How to study each domain", "terms": [{"term": "Active recall over rereading", "short": "Close the lesson and explain the concept from memory. It teaches far more than a second read."}, {"term": "Recap as spaced repetition", "short": "Revisit the domain recap a few days after the lessons, right before the checkpoint."}, {"term": "Think like a technician", "short": "Most SY0-701 questions describe a scenario and ask what you''d do next, not just what a term means."}]}, {"type": "scenario", "prompt": "A help desk analyst notices a user''s account logging in from two countries within ten minutes. What should the analyst do **first**?", "choices": [{"id": "a", "text": "Delete the user''s account"}, {"id": "b", "text": "Escalate it following the incident response procedure"}, {"id": "c", "text": "Ignore it, it''s probably a VPN"}, {"id": "d", "text": "Reimage the user''s laptop"}], "answer": "b", "why": "The first step is to categorize what you''re seeing (a possible compromised account) and follow the defined process, here escalating per the incident response procedure.", "trap": "Deleting the account or reimaging feels decisive, but jumping to a drastic fix before following process is rarely the best first answer."}, {"type": "callout", "variant": "tip", "text": "When a question gives you a scenario, decide what''s being described (an attack, a control, a document) before reading the choices. The choices often test whether you categorized it correctly."}]'::jsonb where id = 'c94d8831-77da-4c5b-bd85-bc709703d9d4';

-- Security Control Categories and Types
update lessons set content_blocks = '[{"text": "Security Control Categories and Types", "type": "title", "overview": "Two ways to classify any security control: what kind of control it is (category) and what it''s trying to do (type).", "examContext": "Heavily tested as \"classify this control\" scenario questions, you''ll be given a control and asked to name its category and/or type."}, {"type": "paragraph", "text": "Every control can be classified two independent ways: by **category** (what kind of control it is) and by **type** (what job it does). A locked server room door is a **physical** control that is **preventive** in type."}, {"type": "term_set", "heading": "Control categories: what kind of control", "terms": [{"term": "Technical", "short": "Implemented through technology: firewalls, encryption, ACLs, antivirus."}, {"term": "Managerial", "short": "Policy and oversight: risk assessments, security policies, background checks."}, {"term": "Operational", "short": "Carried out by people day to day: awareness training, incident procedures, configuration management."}, {"term": "Physical", "short": "Restricts physical access: fences, locks, badge readers, guards, lighting."}]}, {"type": "compare", "heading": "Control types: what the control does", "columns": ["What it does", "Example"], "rows": [{"label": "Preventive", "values": ["Stops an incident before it happens", "A firewall blocking traffic; a locked door"]}, {"label": "Deterrent", "values": ["Discourages without physically stopping", "Warning signs; visible cameras"]}, {"label": "Detective", "values": ["Identifies that something happened", "IDS alerts; reviewing camera footage"]}, {"label": "Corrective", "values": ["Reduces impact after an incident", "Restoring from backup; patching"]}, {"label": "Compensating", "values": ["An alternative when the primary control isn''t feasible", "Extra monitoring on an unpatchable legacy system"]}, {"label": "Directive", "values": ["Tells people what they must do", "A policy requiring badges; a posted procedure"]}]}, {"type": "compare", "heading": "The pair most often confused", "columns": ["Deterrent", "Preventive", "Detective"], "rows": [{"label": "Example", "values": ["\"Premises under video surveillance\" sign", "A locked gate", "The camera recording footage"]}, {"label": "Stops someone?", "values": ["No, discourages", "Yes, physically", "No, records"]}]}, {"type": "scenario", "prompt": "A company can''t install endpoint protection on an old lab machine, so it isolates it on its own VLAN and monitors its traffic closely. What type of control is this?", "choices": [{"id": "a", "text": "Preventive"}, {"id": "b", "text": "Corrective"}, {"id": "c", "text": "Compensating"}, {"id": "d", "text": "Directive"}], "answer": "c", "why": "An alternative control used because the primary one isn''t feasible is compensating."}, {"type": "scenario", "prompt": "A security awareness training program for all staff falls into which control category?", "choices": [{"id": "a", "text": "Technical"}, {"id": "b", "text": "Managerial"}, {"id": "c", "text": "Operational"}, {"id": "d", "text": "Physical"}], "answer": "c", "why": "Training is carried out by people day to day: operational.", "trap": "Managerial is close, because a policy requires the training, but delivering it is an operational activity."}, {"type": "callout", "variant": "tip", "text": "Category = what kind (technical, managerial, operational, physical). Type = what it does. A sign deters; a gate prevents; a camera detects."}]'::jsonb where id = 'f01b56c6-0410-42cc-aaf5-0e2895e2db56';

-- Foundational Security Concepts: CIA, AAA, Non-Repudiation, and Zero Trust
update lessons set content_blocks = '[{"text": "Foundational Security Concepts: CIA, AAA, Non-Repudiation, and Zero Trust", "type": "title", "overview": "The core vocabulary the rest of the exam is built on: the CIA triad, AAA services, non-repudiation, and zero trust.", "examContext": "These terms appear as building blocks inside nearly every other domain''s scenario questions, not just as standalone questions here."}, {"type": "term_set", "heading": "The CIA triad", "terms": [{"term": "Confidentiality", "short": "No unauthorized disclosure. Encryption, access controls, need to know.", "mark": "C"}, {"term": "Integrity", "short": "No unauthorized modification. Hashing, digital signatures, change control.", "mark": "I"}, {"term": "Availability", "short": "Accessible when needed. Redundancy, backups, DR planning.", "mark": "A"}], "diagram": {"kind": "triad", "points": [{"label": "Confidentiality"}, {"label": "Integrity"}, {"label": "Availability"}]}}, {"type": "diagram", "heading": "AAA: who can do what", "diagram": {"kind": "flow", "steps": [{"label": "Authentication", "note": "Prove who you are: password, fingerprint, smart card"}, {"label": "Authorization", "note": "Decide what you''re allowed to do"}, {"label": "Accounting", "note": "Log what was done, by whom, and when"}]}}, {"type": "key_term", "term": "Non-repudiation", "definition": "Preventing someone from credibly denying an action, usually through digital signatures and audit logs.", "example": "A manager signs a purchase approval digitally. When she later claims she never approved it, the signature shows only her private key could have produced it."}, {"type": "compare", "heading": "Zero trust", "columns": ["Control plane", "Data plane"], "rows": [{"label": "Job", "values": ["Decides policy", "Enforces it on each request"]}, {"label": "Pieces", "values": ["Adaptive identity, policy engine and administrator, threat scope reduction", "Subjects and systems, policy enforcement points"]}], "intro": "\"Never trust, always verify\" for every request, wherever it comes from, instead of trusting anything inside the perimeter."}, {"type": "scenario", "prompt": "A user who''s already logged in is asked to re-verify before opening a sensitive HR system, and the decision considers her device''s health and location. Which concept is this?", "choices": [{"id": "a", "text": "Defense in depth"}, {"id": "b", "text": "Zero trust"}, {"id": "c", "text": "Accounting"}, {"id": "d", "text": "Least functionality"}], "answer": "b", "why": "Continuous verification on each request, using context, is zero trust."}, {"type": "scenario", "prompt": "Which AAA function produces the audit trail?", "choices": [{"id": "a", "text": "Authentication"}, {"id": "b", "text": "Authorization"}, {"id": "c", "text": "Accounting"}, {"id": "d", "text": "Availability"}], "answer": "c", "why": "Accounting records who did what and when."}, {"type": "callout", "variant": "tip", "text": "CIA protects data; AAA controls access. Accounting is the audit trail. Zero trust: control plane decides, data plane enforces."}]'::jsonb where id = 'c93a9b82-52ce-49f3-b0f9-2f88118da13f';

-- Physical Security Controls and Deception Technology
update lessons set content_blocks = '[{"text": "Physical Security Controls and Deception Technology", "type": "title", "overview": "Physical barriers that keep people out, and deliberately fake assets designed to catch attackers who get in anyway.", "examContext": "Expect scenario questions naming a specific physical control or a specific decoy technology and asking you to identify it."}, {"type": "term_set", "heading": "Physical security controls", "terms": [{"term": "Bollards", "short": "Sturdy posts that stop vehicles but not pedestrians."}, {"term": "Access control vestibule", "short": "Two interlocking doors; one opens at a time. Stops tailgating."}, {"term": "Fencing", "short": "A perimeter barrier, often with deterrent signage."}, {"term": "Video surveillance", "short": "Detective when reviewed; deterrent when visible."}, {"term": "Security guard", "short": "Adapts to situations automation can''t."}, {"term": "Access badge", "short": "Physical or RFID credential for entry."}, {"term": "Lighting", "short": "Supports surveillance and deters intruders."}, {"term": "Sensors", "short": "Infrared, pressure, microwave and ultrasonic detection of presence or motion."}]}, {"type": "compare", "heading": "Deception technology", "columns": ["What it is", "Scale"], "rows": [{"label": "Honeypot", "values": ["A decoy system that looks like a real target", "One system"]}, {"label": "Honeynet", "values": ["A whole decoy network of honeypots", "A network"]}, {"label": "Honeyfile", "values": ["A fake, monitored file such as passwords.xlsx", "One file"]}, {"label": "Honeytoken", "values": ["A fake credential, API key or record whose use signals an intrusion", "One data value"]}], "intro": "Fake, monitored assets that catch attackers who get past other defenses. Nobody legitimate should ever touch them."}, {"type": "key_term", "term": "Honeytoken", "definition": "A planted piece of fake data. Any use of it is proof of unauthorized access.", "example": "A fake AWS access key is left in a configuration file. Months later, an alert fires when someone tries to use it from overseas, revealing the file was stolen."}, {"type": "scenario", "prompt": "A company wants to stop vehicles from driving into its lobby while still letting people walk through. What should it install?", "choices": [{"id": "a", "text": "An access control vestibule"}, {"id": "b", "text": "Bollards"}, {"id": "c", "text": "Fencing"}, {"id": "d", "text": "Motion sensors"}], "answer": "b", "why": "Bollards block vehicles without blocking pedestrians."}, {"type": "scenario", "prompt": "A security team plants a fake customer record in the CRM and alerts if it ever appears outside the company. What is this?", "choices": [{"id": "a", "text": "Honeypot"}, {"id": "b", "text": "Honeynet"}, {"id": "c", "text": "Honeyfile"}, {"id": "d", "text": "Honeytoken"}], "answer": "d", "why": "A single planted data value is a honeytoken.", "trap": "A honeyfile is also bait, but it''s a whole file rather than a data value."}, {"type": "callout", "variant": "tip", "text": "Honeypot = one system, honeynet = a network, honeyfile = a file, honeytoken = a data value. Bollards stop vehicles; vestibules stop tailgating."}]'::jsonb where id = '34077231-42df-4f6d-82bd-b0d2df3f99c2';

-- Change Management and Its Security Impact
update lessons set content_blocks = '[{"text": "Change Management and Its Security Impact", "type": "title", "overview": "The business process and technical safeguards around making changes to production systems without breaking or exposing them.", "examContext": "Frequently tested as \"what step of the change process was skipped\" scenario questions."}, {"type": "paragraph", "text": "Uncontrolled changes are among the most common causes of incidents. Change itself isn''t the risk; skipping the process around it is."}, {"type": "diagram", "heading": "The change process", "diagram": {"kind": "flow", "steps": [{"label": "Request and ownership", "note": "A named owner and the stakeholders"}, {"label": "Impact analysis", "note": "What could break, and how badly"}, {"label": "Test", "note": "Evidence it works before production"}, {"label": "Approval", "note": "Usually a Change Advisory Board"}, {"label": "Implement in a window", "note": "Scheduled maintenance window, following the SOP"}, {"label": "Document", "note": "Update diagrams, policies and version control"}]}}, {"type": "key_term", "term": "Backout plan", "definition": "The specific steps to reverse a change if it fails. The most frequently tested missing piece.", "example": "A firewall update blocks the payroll system. With a backout plan, the previous rule set is restored in five minutes; without one, payroll is down all afternoon."}, {"type": "term_set", "heading": "Technical considerations", "terms": [{"term": "Allow and deny lists", "short": "Rules that may need updating for the change."}, {"term": "Restricted activities", "short": "What''s permitted during the change window."}, {"term": "Downtime and restarts", "short": "Whether services must stop or restart."}, {"term": "Legacy applications and dependencies", "short": "What else might break."}, {"term": "Documentation and version control", "short": "So the change history is tracked and reversible."}]}, {"type": "scenario", "prompt": "A patch breaks a critical application, and the team spends six hours figuring out how to undo it. Which part of change management was missing?", "choices": [{"id": "a", "text": "Impact analysis"}, {"id": "b", "text": "Maintenance window"}, {"id": "c", "text": "Backout plan"}, {"id": "d", "text": "Stakeholder list"}], "answer": "c", "why": "A documented way to reverse the change would have made recovery quick."}, {"type": "scenario", "prompt": "Who is typically responsible for approving a significant change before it''s implemented?", "choices": [{"id": "a", "text": "The change owner alone"}, {"id": "b", "text": "A Change Advisory Board"}, {"id": "c", "text": "The help desk"}, {"id": "d", "text": "The vendor"}], "answer": "b", "why": "The CAB reviews and approves changes."}, {"type": "callout", "variant": "tip", "text": "Every change needs an owner, impact analysis, testing, approval, a window, a backout plan, and updated documentation."}]'::jsonb where id = '3a58aa39-fa09-4412-a7cc-fe7d83a0a37f';

-- Cryptographic Solutions: PKI, Encryption, Hashing, and Certificates
update lessons set content_blocks = '[{"text": "Cryptographic Solutions: PKI, Encryption, Hashing, and Certificates", "type": "title", "overview": "The building blocks of applied cryptography: PKI and certificates, encryption at various levels, hashing, digital signatures, and the hardware that protects keys.", "examContext": "One of the densest sub-objectives on the exam, expect several standalone questions plus cryptography woven into scenario questions elsewhere."}, {"type": "term_set", "heading": "PKI building blocks", "terms": [{"term": "Certificate Authority (CA)", "short": "Issues digital certificates."}, {"term": "CSR", "short": "Certificate Signing Request: your public key and identity, sent to a CA."}, {"term": "CRL / OCSP", "short": "A revocation list / a real-time revocation check."}, {"term": "Root of trust", "short": "The inherently trusted certificate or hardware everything else is checked against."}, {"term": "Self-signed certificate", "short": "Signed by its creator. Fine for internal testing, untrusted by outsiders by default."}]}, {"type": "compare", "heading": "Symmetric vs. asymmetric encryption", "columns": ["Symmetric", "Asymmetric"], "rows": [{"label": "Keys", "values": ["One shared key", "Public and private key pair"]}, {"label": "Speed", "values": ["Fast", "Slow"]}, {"label": "Used for", "values": ["Bulk data", "Key exchange and digital signatures"]}], "intro": "Encryption can be applied at many levels: full disk, partition, volume, file, database or individual record. TLS and IPsec protect data in transit."}, {"type": "term_set", "heading": "Protecting passwords and proving integrity", "terms": [{"term": "Hashing", "short": "One-way, fixed-length digest for integrity. Can''t be reversed."}, {"term": "Salting", "short": "Random data added before hashing, so identical passwords hash differently. Beats rainbow tables."}, {"term": "Key stretching", "short": "Deliberately slow derivation (PBKDF2, bcrypt) to make brute force impractical."}, {"term": "Digital signature", "short": "A hash encrypted with the sender''s private key: integrity and non-repudiation."}]}, {"type": "compare", "heading": "TPM vs. HSM vs. secure enclave", "columns": ["TPM", "HSM", "Secure enclave"], "rows": [{"label": "Is", "values": ["A chip in one device", "A dedicated, tamper-resistant appliance", "An isolated area inside a processor"]}, {"label": "Protects", "values": ["That device''s keys", "Keys for many servers or the organization", "Sensitive operations like key handling"]}], "cue": ["\"this laptop''s built-in chip\"", "\"rack-mounted\", \"at scale\"", "\"inside the processor\""]}, {"type": "compare", "heading": "Obfuscation techniques", "columns": ["How it works", "Example"], "rows": [{"label": "Tokenization", "values": ["Swaps sensitive data for a token mapped elsewhere", "A card number replaced by tok_8f2a in the order database"]}, {"label": "Data masking", "values": ["Hides part of a value", "Showing only •••• 4821"]}, {"label": "Steganography", "values": ["Hides data inside other data", "A message hidden in an image''s pixels"]}]}, {"type": "scenario", "prompt": "An e-commerce site wants card numbers out of its order database entirely, with a separate secure system mapping placeholders back to real numbers. Which technique fits?", "choices": [{"id": "a", "text": "Data masking"}, {"id": "b", "text": "Tokenization"}, {"id": "c", "text": "Hashing"}, {"id": "d", "text": "Steganography"}], "answer": "b", "why": "Replacing data with a token that maps back in a separate vault is tokenization.", "trap": "Masking hides part of the number but the real value is still stored."}, {"type": "scenario", "prompt": "Which makes brute-forcing stolen password hashes far slower?", "choices": [{"id": "a", "text": "Salting"}, {"id": "b", "text": "Key stretching"}, {"id": "c", "text": "Tokenization"}, {"id": "d", "text": "Self-signed certificates"}], "answer": "b", "why": "Key stretching makes each guess expensive. Salting defeats precomputed tables but doesn''t slow each guess."}, {"type": "callout", "variant": "tip", "text": "TPM = one device; HSM = appliance at scale. Salting beats rainbow tables; key stretching slows brute force. Tokenization swaps; masking hides."}]'::jsonb where id = '2be4fd54-01c6-400d-aa2e-354bed86e1e2';

-- Domain 1 Recap
update lessons set content_blocks = '[{"text": "Domain 1 Recap: General Security Concepts", "type": "title", "overview": "A condensed pass over every lesson in this domain, control categories/types, CIA/AAA/zero trust, physical and deception controls, change management, and cryptographic solutions.", "examContext": "This recap has no questions of its own; the Domain Checkpoint right after it draws fresh scenario questions from everything covered across all 5 lessons."}, {"type": "term_set", "heading": "Controls and concepts", "terms": [{"term": "Categories", "short": "Technical, managerial, operational, physical."}, {"term": "Types", "short": "Preventive, deterrent, detective, corrective, compensating, directive."}, {"term": "CIA / AAA", "short": "Protect data / control access. Accounting is the audit trail."}, {"term": "Non-repudiation", "short": "Signatures and logs."}, {"term": "Zero trust", "short": "Verify every request. Control plane decides, data plane enforces."}]}, {"type": "term_set", "heading": "Physical, deception and change", "terms": [{"term": "Bollards / vestibule", "short": "Stop vehicles / stop tailgating."}, {"term": "Honeypot, honeynet, honeyfile, honeytoken", "short": "System, network, file, data value."}, {"term": "Change management", "short": "Owner, impact analysis, testing, CAB approval, window, documentation."}, {"term": "Backout plan", "short": "The most tested missing piece."}]}, {"type": "term_set", "heading": "Cryptography", "terms": [{"term": "PKI", "short": "CA issues; CSR requests; CRL and OCSP check revocation."}, {"term": "Symmetric / asymmetric", "short": "Shared key, fast / key pair, key exchange and signatures."}, {"term": "Salting / key stretching", "short": "Beats rainbow tables / slows brute force."}, {"term": "TPM / HSM", "short": "One device / appliance at scale."}, {"term": "Tokenization / masking / steganography", "short": "Swap / hide part / hide inside."}]}, {"type": "scenario", "prompt": "A visible \"Alarm monitored 24/7\" sticker on a door is which control type?", "choices": [{"id": "a", "text": "Preventive"}, {"id": "b", "text": "Deterrent"}, {"id": "c", "text": "Detective"}, {"id": "d", "text": "Corrective"}], "answer": "b", "why": "It discourages without stopping anyone."}, {"type": "scenario", "prompt": "Which device stores encryption keys bound to a single laptop?", "choices": [{"id": "a", "text": "HSM"}, {"id": "b", "text": "TPM"}, {"id": "c", "text": "CA"}, {"id": "d", "text": "Key management system"}], "answer": "b", "why": "The TPM is a chip on that device."}, {"type": "scenario", "prompt": "A change fails and can''t be reversed quickly. What was missing?", "choices": [{"id": "a", "text": "CAB approval"}, {"id": "b", "text": "Backout plan"}, {"id": "c", "text": "Maintenance window"}, {"id": "d", "text": "SOP"}], "answer": "b", "why": "The backout plan defines how to reverse it."}, {"type": "callout", "variant": "info", "text": "When you''re ready, head to the Domain Checkpoint: fresh scenarios from all five lessons in this domain."}]'::jsonb where id = '0cd6c679-30a4-42b2-913c-d685488427e8';

-- Threat Actors: Types and Motivations
update lessons set content_blocks = '[{"text": "Threat Actors: Types and Motivations", "type": "title", "overview": "The categories of people and groups behind attacks, and the motivations that distinguish them.", "examContext": "Expect scenario questions describing an attack''s characteristics and asking you to identify the likely actor type and motivation behind it."}, {"type": "paragraph", "text": "Not every attacker has the same resources, skill or goal. The exam expects you to match a described attack to the actor most likely behind it."}, {"type": "compare", "heading": "Threat actors", "columns": ["Resources and skill", "Typical motivation"], "rows": [{"label": "Nation-state", "values": ["Very high; long, patient campaigns", "Espionage, disruption, war"]}, {"label": "Organized crime", "values": ["High; runs like a business", "Financial gain: ransomware, fraud"]}, {"label": "Hacktivist", "values": ["Varies", "Political or philosophical belief"]}, {"label": "Insider threat", "values": ["Legitimate access already", "Revenge, money, ideology"]}, {"label": "Unskilled attacker", "values": ["Low; uses others'' tools", "Notoriety, disruption"]}], "intro": "Resources and sophistication are the fastest way to rule actors in or out."}, {"type": "key_term", "term": "Shadow IT", "definition": "Not an attacker but a risk source: staff using hardware, software or cloud services outside IT''s visibility and control.", "example": "A sales team stores client contracts in a free file-sharing app nobody in IT knows about, so it''s never backed up or monitored."}, {"type": "term_set", "heading": "Motivations to recognize", "terms": [{"term": "Data exfiltration", "short": "Stealing valuable information."}, {"term": "Espionage", "short": "Covert intelligence gathering, usually nation-state."}, {"term": "Service disruption", "short": "Knocking systems offline."}, {"term": "Blackmail", "short": "Extortion with stolen data or access."}, {"term": "Financial gain", "short": "The main driver for organized crime."}, {"term": "Philosophical or political", "short": "The hacktivist''s motive."}, {"term": "Ethical", "short": "White-hat work such as responsible disclosure."}, {"term": "Revenge", "short": "A disgruntled insider''s most common motive."}]}, {"type": "scenario", "prompt": "A multi-year campaign uses custom malware never seen before to quietly steal defense research from several contractors. Which actor is most likely?", "choices": [{"id": "a", "text": "Unskilled attacker"}, {"id": "b", "text": "Hacktivist"}, {"id": "c", "text": "Nation-state"}, {"id": "d", "text": "Insider threat"}], "answer": "c", "why": "Long-term, highly resourced, custom tooling and espionage goals point to a nation-state."}, {"type": "scenario", "prompt": "A recently fired database administrator uses a still-active account to delete customer records. What is the actor and motive?", "choices": [{"id": "a", "text": "Organized crime, financial gain"}, {"id": "b", "text": "Insider threat, revenge"}, {"id": "c", "text": "Hacktivist, political belief"}, {"id": "d", "text": "Nation-state, espionage"}], "answer": "b", "why": "A former employee misusing access out of grievance is an insider acting from revenge."}, {"type": "callout", "variant": "tip", "text": "Sophistication and resources rule actors out fastest. Money = organized crime; ideology = hacktivist; espionage = nation-state; grievance = insider."}]'::jsonb where id = '8b33cc58-1d13-49f2-8758-8c8975c43b0c';

-- Threat Vectors and Attack Surfaces
update lessons set content_blocks = '[{"text": "Threat Vectors and Attack Surfaces", "type": "title", "overview": "The specific paths and exposed surfaces attackers use to gain initial access to a target.", "examContext": "Scenario questions here describe how an attack STARTED, your job is to name the vector, not the eventual payload."}, {"type": "compare", "heading": "Vector vs. attack surface", "columns": ["Threat vector", "Attack surface"], "rows": [{"label": "Is", "values": ["The **path** an attack takes in", "**Everything exposed** that could be attacked"]}, {"label": "Example", "values": ["A phishing email", "Every open port, account, app and unpatched system"]}, {"label": "Defense", "values": ["Block or harden the path", "Shrink it: fewer services, accounts and exposures"]}]}, {"type": "term_set", "heading": "Common vectors", "terms": [{"term": "Message-based", "short": "Email, SMS (smishing), instant messaging."}, {"term": "Image- and file-based", "short": "Malicious code hidden in images, documents or executables."}, {"term": "Voice call", "short": "Vishing: social engineering by phone."}, {"term": "Removable device", "short": "Infected USB drives left to be found."}, {"term": "Vulnerable or unsupported software", "short": "Exploitable flaws, or no more patches at all."}, {"term": "Unsecure networks", "short": "Weak wireless, wired or Bluetooth protections."}, {"term": "Open ports and default credentials", "short": "Unneeded services; factory passwords never changed."}, {"term": "Supply chain", "short": "Through a trusted vendor or managed service provider."}, {"term": "Human vectors", "short": "Social engineering aimed at people."}]}, {"type": "key_term", "term": "Supply chain vector", "definition": "The entry point is a trusted third party rather than the target itself. Hard to defend because it arrives through a relationship you already trust.", "example": "Attackers compromise a managed service provider''s remote management tool and push ransomware to every one of its clients at once."}, {"type": "scenario", "prompt": "An attacker drops USB drives labeled \"Q4 Bonuses\" in a company parking lot, and an employee plugs one in. What vector is this?", "choices": [{"id": "a", "text": "Message-based"}, {"id": "b", "text": "Removable device"}, {"id": "c", "text": "Supply chain"}, {"id": "d", "text": "Unsecure network"}], "answer": "b", "why": "The infection arrived on a physical removable device.", "trap": "It relies on curiosity, a human factor, but the delivery path is the USB drive."}, {"type": "scenario", "prompt": "Which action most directly reduces the attack surface?", "choices": [{"id": "a", "text": "Buying cyber insurance"}, {"id": "b", "text": "Disabling unused services and closing unneeded ports"}, {"id": "c", "text": "Adding more log sources to the SIEM"}, {"id": "d", "text": "Writing an incident response plan"}], "answer": "b", "why": "Fewer exposed services means less that can be attacked."}, {"type": "callout", "variant": "tip", "text": "Name the vector by how the attack **started**, not what it did later. A trusted third party as the way in means supply chain."}]'::jsonb where id = '51f82c99-a344-4ed2-bd9b-ad9c96cbd9db';

-- Application and Operating System Vulnerabilities
update lessons set content_blocks = '[{"text": "Application and Operating System Vulnerabilities", "type": "title", "overview": "The technical weaknesses inside software and operating systems that attackers exploit directly.", "examContext": "Expect to match a described exploitation technique to its specific vulnerability name."}, {"type": "paragraph", "text": "Application and OS vulnerabilities are flaws in how software is written or configured, rather than in the network path used to reach it."}, {"type": "term_set", "heading": "Vulnerabilities to name", "terms": [{"term": "Memory injection", "short": "Code injected into a running process''s memory, running with its privileges."}, {"term": "Buffer overflow", "short": "More data than a buffer holds, overwriting adjacent memory."}, {"term": "Race condition (TOCTOU)", "short": "State changes between the check and the use."}, {"term": "SQL injection", "short": "Malicious SQL in an input field runs on the database."}, {"term": "Cross-site scripting (XSS)", "short": "Injected script runs in other users'' browsers."}, {"term": "Malicious update", "short": "Compromised code disguised as a legitimate update."}, {"term": "OS-based", "short": "Flaws in the operating system, exposed until patched."}]}, {"type": "compare", "heading": "SQL injection vs. XSS", "columns": ["SQL injection", "Cross-site scripting"], "rows": [{"label": "Where input goes", "values": ["Into a **database query**", "Into a **web page** other users view"]}, {"label": "Who runs the payload", "values": ["The database server", "Victims'' browsers"]}, {"label": "Main defense", "values": ["Parameterized queries", "Output encoding"]}], "cue": ["\"query\", \"database\", '' OR 1=1", "\"<script>\", \"other users'' browsers\""]}, {"type": "key_term", "term": "Buffer overflow", "definition": "Writing past the end of allocated memory. Can crash a program or let an attacker run their own code.", "example": "A 32-character username field accepts 2,000 characters, and the extra data overwrites the program''s return address."}, {"type": "scenario", "prompt": "A comment field on a forum stores a script that runs in every visitor''s browser and sends their session cookie to an attacker. What is this?", "choices": [{"id": "a", "text": "SQL injection"}, {"id": "b", "text": "Cross-site scripting"}, {"id": "c", "text": "Buffer overflow"}, {"id": "d", "text": "Memory injection"}], "answer": "b", "why": "Script rendered into a page that other users view is XSS."}, {"type": "scenario", "prompt": "An application checks a user''s permissions on a file, then opens it a few milliseconds later; an attacker swaps the file in between. What is this?", "choices": [{"id": "a", "text": "Race condition"}, {"id": "b", "text": "Buffer overflow"}, {"id": "c", "text": "Malicious update"}, {"id": "d", "text": "SQL injection"}], "answer": "a", "why": "A change between time-of-check and time-of-use is a race condition (TOCTOU)."}, {"type": "callout", "variant": "tip", "text": "Input concatenated into a query: SQL injection. Input rendered to other users: XSS. Too much data for a buffer: overflow."}]'::jsonb where id = '34d0dee5-5c62-4f34-8932-7298e1fa4298';

-- Cloud, Supply Chain, and Virtualization Vulnerabilities
update lessons set content_blocks = '[{"text": "Cloud, Supply Chain, and Virtualization Vulnerabilities", "type": "title", "overview": "Vulnerability classes specific to modern infrastructure: cloud environments, third-party relationships, and virtualized systems.", "examContext": "These vulnerabilities are increasingly common on the exam as organizations shift workloads to cloud and virtualized environments."}, {"type": "term_set", "heading": "Modern infrastructure vulnerabilities", "terms": [{"term": "Cloud misconfiguration", "short": "A public storage bucket, an over-permissive IAM role: exposure by mistake."}, {"term": "VM escape", "short": "Breaking out of a VM to reach the hypervisor or other VMs."}, {"term": "Resource reuse", "short": "Memory or storage not cleared between tenants, leaking one''s data to another."}, {"term": "Zero-day", "short": "Unknown to the vendor, so unpatched: zero days to fix it."}]}, {"type": "compare", "heading": "Three supply chain sources", "columns": ["Service provider", "Hardware provider", "Software provider"], "rows": [{"label": "Risk", "values": ["An MSP''s access to your systems", "Compromised components before they arrive", "A vulnerable or malicious dependency"]}, {"label": "Example", "values": ["An attacker uses an MSP''s remote tool", "Counterfeit network cards with implanted firmware", "A popular library with a backdoor"]}]}, {"type": "key_term", "term": "Cloud misconfiguration", "definition": "The customer''s mistake, not a flaw in the provider''s platform.", "example": "A developer sets a storage bucket of customer invoices to public for a quick test and forgets to change it back."}, {"type": "scenario", "prompt": "Millions of customer records are found in a cloud storage bucket that anyone on the internet can list. What is the most likely cause?", "choices": [{"id": "a", "text": "A zero-day in the cloud provider"}, {"id": "b", "text": "A cloud misconfiguration by the customer"}, {"id": "c", "text": "VM escape"}, {"id": "d", "text": "Resource reuse"}], "answer": "b", "why": "A publicly exposed bucket is almost always a customer configuration error."}, {"type": "scenario", "prompt": "Attackers exploit a flaw the software vendor doesn''t know about and has never patched. What is it called?", "choices": [{"id": "a", "text": "Zero-day"}, {"id": "b", "text": "Legacy vulnerability"}, {"id": "c", "text": "Misconfiguration"}, {"id": "d", "text": "Supply chain vulnerability"}], "answer": "a", "why": "Unknown to the vendor and unpatched: a zero-day."}, {"type": "callout", "variant": "tip", "text": "Public bucket or broad IAM role = misconfiguration. Breaking out of a VM = VM escape. Unknown to the vendor = zero-day."}]'::jsonb where id = 'f4c7d851-7fd4-4ef0-b940-7e960bb24b7f';

-- Malware Types and Indicators
update lessons set content_blocks = '[{"text": "Malware Types and Indicators", "type": "title", "overview": "The major categories of malicious software and the specific behavior that identifies each one.", "examContext": "You''ll be given a described symptom or behavior and asked to name the malware type responsible."}, {"type": "compare", "heading": "Malware by behavior", "columns": ["Defining behavior"], "rows": [{"label": "Ransomware", "values": ["Encrypts files and demands payment for the key"]}, {"label": "Trojan", "values": ["Disguised as legitimate software the user installs"]}, {"label": "Worm", "values": ["Spreads across networks **by itself**"]}, {"label": "Virus", "values": ["Attaches to files; needs a **user** to run it"]}, {"label": "Spyware", "values": ["Secretly monitors and sends off activity"]}, {"label": "Keylogger", "values": ["Records every keystroke, often for credentials"]}, {"label": "Bloatware", "values": ["Unwanted bundled software; not always malicious, but adds attack surface"]}, {"label": "Logic bomb", "values": ["Lies dormant until a date or event triggers it"]}, {"label": "Rootkit", "values": ["Keeps privileged access while hiding from the OS and security tools"]}]}, {"type": "compare", "heading": "Worm vs. virus", "columns": ["Worm", "Virus"], "rows": [{"label": "Needs a host file?", "values": ["No", "Yes"]}, {"label": "Needs user action?", "values": ["No", "Yes"]}, {"label": "Spreads", "values": ["Network to network on its own", "When infected files are opened and shared"]}], "intro": "The most tested pair in this lesson."}, {"type": "key_term", "term": "Rootkit", "definition": "Malware that hides itself while keeping admin-level control. Hard to detect from inside the infected OS.", "example": "Antivirus scans come back clean, but booting the machine from a trusted USB drive reveals a hidden driver that''s been intercepting system calls."}, {"type": "scenario", "prompt": "Malware infects hundreds of servers overnight by exploiting an unpatched service, with no emails opened and no users involved. What is it?", "choices": [{"id": "a", "text": "Virus"}, {"id": "b", "text": "Trojan"}, {"id": "c", "text": "Worm"}, {"id": "d", "text": "Logic bomb"}], "answer": "c", "why": "Self-propagation with no user action is a worm."}, {"type": "scenario", "prompt": "A disgruntled developer adds code that will delete the payroll database if his account is ever disabled. What is this?", "choices": [{"id": "a", "text": "Rootkit"}, {"id": "b", "text": "Logic bomb"}, {"id": "c", "text": "Spyware"}, {"id": "d", "text": "Ransomware"}], "answer": "b", "why": "Dormant code waiting for a trigger condition is a logic bomb."}, {"type": "callout", "variant": "tip", "text": "Worm spreads itself; virus needs a user. Trojan pretends; rootkit hides; logic bomb waits."}]'::jsonb where id = '661c6b2c-3f1a-4b7e-9761-dfe9b547264f';

-- Physical, Network, and Application Attack Indicators
update lessons set content_blocks = '[{"text": "Physical, Network, and Application Attack Indicators", "type": "title", "overview": "Recognizing attacks by category: physical intrusion techniques, network-layer attacks, and application-layer attacks.", "examContext": "One of the exam''s densest scenario areas, expect several questions describing symptoms and asking which specific attack matches."}, {"type": "term_set", "heading": "Physical attacks", "terms": [{"term": "Brute force", "short": "Repeatedly trying a lock or PIN pad until it opens."}, {"term": "RFID cloning", "short": "Copying a badge or fob''s credentials to make a duplicate."}, {"term": "Environmental", "short": "Tampering with HVAC, power or fire suppression to cause damage."}]}, {"type": "term_set", "heading": "Network attacks", "terms": [{"term": "DDoS", "short": "Traffic from many sources overwhelms a service, often amplified or reflected."}, {"term": "On-path", "short": "Attacker sits between two parties to read or change traffic (formerly man-in-the-middle)."}, {"term": "Credential replay", "short": "Reusing a captured valid token or session to impersonate a user."}, {"term": "DNS attack", "short": "Poisoning resolution to send users to a malicious site."}]}, {"type": "diagram", "heading": "An amplified, reflected DDoS", "diagram": {"kind": "flow", "steps": [{"label": "Attacker sends small requests", "note": "With the victim''s address spoofed as the source"}, {"label": "Third-party servers reply", "note": "With much larger responses"}, {"label": "Replies flood the victim", "note": "The victim never talked to the attacker"}]}}, {"type": "term_set", "heading": "Application attacks", "terms": [{"term": "Privilege escalation", "short": "Gaining more access than granted."}, {"term": "Forgery (CSRF)", "short": "Tricking a logged-in user''s browser into sending an unwanted request."}, {"term": "Directory traversal", "short": "Paths like ../../ to read files outside the web root."}, {"term": "Injection", "short": "Malicious code or commands in an input field."}]}, {"type": "scenario", "prompt": "A web server log shows requests like /download?file=../../../../etc/passwd. What attack is this?", "choices": [{"id": "a", "text": "Injection"}, {"id": "b", "text": "Directory traversal"}, {"id": "c", "text": "CSRF"}, {"id": "d", "text": "Credential replay"}], "answer": "b", "why": "Climbing out of the intended folder with ../ sequences is directory traversal."}, {"type": "scenario", "prompt": "A user visits a malicious page while logged into her bank, and the page silently submits a transfer from her account. What is this?", "choices": [{"id": "a", "text": "Cross-site scripting"}, {"id": "b", "text": "Cross-site request forgery"}, {"id": "c", "text": "On-path attack"}, {"id": "d", "text": "DNS poisoning"}], "answer": "b", "why": "Making the victim''s authenticated browser send an unwanted request is CSRF.", "trap": "XSS also involves browsers, but it runs script inside the trusted site rather than forging a request to it."}, {"type": "callout", "variant": "tip", "text": "../ in a path = traversal. Forged request from a logged-in browser = CSRF. Small requests, huge replies at the victim = amplified DDoS."}]'::jsonb where id = '0d4c0ee9-b2d7-4192-97c1-393f5396a1ba';

-- Cryptographic and Password Attack Indicators
update lessons set content_blocks = '[{"text": "Cryptographic and Password Attack Indicators", "type": "title", "overview": "Attacks that target cryptographic weaknesses directly, and the common ways attackers try to obtain or guess passwords.", "examContext": "A smaller but consistently tested sub-objective, expect a handful of direct \"name this attack\" questions."}, {"type": "term_set", "heading": "Cryptographic attacks", "terms": [{"term": "Downgrade", "short": "Forcing a weaker, older protocol or cipher."}, {"term": "Collision", "short": "Two different inputs producing the same hash."}, {"term": "Birthday", "short": "Exploits how quickly collisions become likely as inputs grow."}]}, {"type": "compare", "heading": "Password attacks", "columns": ["Pattern", "Defeated by"], "rows": [{"label": "Password spraying", "values": ["**One** common password against **many** accounts", "MFA, banning common passwords, monitoring"]}, {"label": "Brute force", "values": ["**Many** passwords against **one** account", "Lockout, MFA"]}, {"label": "Dictionary", "values": ["A list of likely words and passwords", "Strong, uncommon passwords"]}, {"label": "Rainbow table", "values": ["Precomputed hashes reversed into passwords", "**Salting**"]}]}, {"type": "key_term", "term": "Downgrade attack", "definition": "Manipulating negotiation so both sides use an older, weaker version.", "example": "An attacker on hotel Wi-Fi interferes with the handshake so a laptop falls back to an outdated TLS version with known weaknesses."}, {"type": "scenario", "prompt": "Over one hour, a login portal sees \"Spring2026!\" tried once against each of 3,000 different accounts. What is this?", "choices": [{"id": "a", "text": "Brute force"}, {"id": "b", "text": "Password spraying"}, {"id": "c", "text": "Rainbow table attack"}, {"id": "d", "text": "Dictionary attack against one user"}], "answer": "b", "why": "One password across many accounts, to stay under lockout thresholds, is spraying."}, {"type": "scenario", "prompt": "Which control defeats rainbow table attacks on stored password hashes?", "choices": [{"id": "a", "text": "Account lockout"}, {"id": "b", "text": "Salting"}, {"id": "c", "text": "TLS"}, {"id": "d", "text": "Password expiration"}], "answer": "b", "why": "Unique salts make precomputed tables useless."}, {"type": "callout", "variant": "tip", "text": "Spraying: one password, many accounts. Brute force: many passwords, one account. Salting kills rainbow tables."}]'::jsonb where id = '709908ab-ea26-46e2-9ecf-97a58d60c1a4';

-- Mitigation Techniques
update lessons set content_blocks = '[{"text": "Mitigation Techniques", "type": "title", "overview": "The defensive techniques used to reduce or eliminate the threats, vectors, and vulnerabilities covered earlier in this domain.", "examContext": "Ties the whole domain together, expect scenario questions asking which mitigation BEST addresses a described threat or vulnerability."}, {"type": "compare", "heading": "Core mitigations", "columns": ["Stops or limits"], "rows": [{"label": "Segmentation", "values": ["How far an attacker or worm can move"]}, {"label": "Access control", "values": ["Who and what can reach a resource"]}, {"label": "Application allow listing", "values": ["Unapproved software from running at all"]}, {"label": "Isolation", "values": ["A compromised or risky system affecting others"]}, {"label": "Patching", "values": ["Known vulnerabilities"]}, {"label": "Encryption", "values": ["Data exposure even if accessed"]}, {"label": "Monitoring", "values": ["Incidents going unnoticed"]}, {"label": "Least privilege", "values": ["The blast radius of a compromised account"]}, {"label": "Configuration enforcement", "values": ["Drift from the secure baseline"]}, {"label": "Decommissioning", "values": ["Exposure from systems no longer needed"]}]}, {"type": "term_set", "heading": "Hardening techniques", "terms": [{"term": "Endpoint protection and host firewalls", "short": "Defend each host directly."}, {"term": "HIPS", "short": "Host-based intrusion prevention."}, {"term": "Disable unused ports and protocols", "short": "Shrink the attack surface."}, {"term": "Change default passwords", "short": "Close the easiest door."}, {"term": "Remove unnecessary software", "short": "Less to exploit and patch."}]}, {"type": "key_term", "term": "Match the root cause", "definition": "The best mitigation addresses why the attack worked, not just what it did.", "example": "A worm tears through a flat network. New antivirus signatures stop this worm; segmentation stops the next one too."}, {"type": "scenario", "prompt": "Ransomware spread from one infected laptop to every server because the network is flat. Which mitigation best addresses the root cause?", "choices": [{"id": "a", "text": "Updated antivirus signatures"}, {"id": "b", "text": "Network segmentation"}, {"id": "c", "text": "Stronger passwords"}, {"id": "d", "text": "Encryption at rest"}], "answer": "b", "why": "Segmentation limits lateral movement, which is why the outbreak spread so far."}, {"type": "scenario", "prompt": "A kiosk should only ever run the check-in app. Which mitigation fits?", "choices": [{"id": "a", "text": "Application allow listing"}, {"id": "b", "text": "Monitoring"}, {"id": "c", "text": "Encryption"}, {"id": "d", "text": "Decommissioning"}], "answer": "a", "why": "Allow listing permits only approved software and blocks everything else."}, {"type": "callout", "variant": "tip", "text": "Pick the mitigation that fixes the root cause. Flat network: segment. Unknown software: allow list. Old unused server: decommission."}]'::jsonb where id = '45127b90-a224-4ffb-8d63-a9db7a25864a';

-- Domain 2 Recap
update lessons set content_blocks = '[{"text": "Domain 2 Recap: Threats, Vulnerabilities, and Mitigations", "type": "title", "overview": "A condensed pass over threat actors, vectors, application/cloud/supply-chain vulnerabilities, malware, attack indicators, and mitigations.", "examContext": "This recap has no questions of its own; the Domain Checkpoint right after it draws fresh scenario questions from everything across all 8 lessons."}, {"type": "term_set", "heading": "Actors and vectors", "terms": [{"term": "Nation-state / organized crime", "short": "Espionage, high resources / money."}, {"term": "Hacktivist / insider / unskilled", "short": "Ideology / revenge or access misuse / borrowed tools."}, {"term": "Vectors", "short": "Message, file, voice, removable device, unsecure network, default credentials, supply chain, human."}]}, {"type": "term_set", "heading": "Vulnerabilities and malware", "terms": [{"term": "Overflow / TOCTOU / SQLi / XSS", "short": "Memory overwrite / timing gap / malicious query / script in others'' browsers."}, {"term": "Misconfiguration / VM escape / zero-day", "short": "Customer error / breaking isolation / unknown and unpatched."}, {"term": "Worm / virus", "short": "Spreads itself / needs a user."}, {"term": "Rootkit / logic bomb", "short": "Hides with privilege / waits for a trigger."}]}, {"type": "term_set", "heading": "Attacks and mitigations", "terms": [{"term": "Amplified DDoS / on-path / replay", "short": "Big replies at the victim / in the middle / reused tokens."}, {"term": "Spraying / brute force / rainbow table", "short": "One password many accounts / many passwords one account / beaten by salting."}, {"term": "Downgrade / collision", "short": "Weaker protocol forced / two inputs, same hash."}, {"term": "Mitigations", "short": "Segment, isolate, least privilege, patch, encrypt, monitor, decommission."}]}, {"type": "scenario", "prompt": "A crafted request returns another folder''s files using ../ sequences. Which attack?", "choices": [{"id": "a", "text": "CSRF"}, {"id": "b", "text": "Directory traversal"}, {"id": "c", "text": "Injection"}, {"id": "d", "text": "Replay"}], "answer": "b", "why": "Path traversal out of the web root."}, {"type": "scenario", "prompt": "Which malware spreads without any user action?", "choices": [{"id": "a", "text": "Virus"}, {"id": "b", "text": "Trojan"}, {"id": "c", "text": "Worm"}, {"id": "d", "text": "Spyware"}], "answer": "c", "why": "Worms self-propagate."}, {"type": "scenario", "prompt": "What best limits how far an intruder can move after a breach?", "choices": [{"id": "a", "text": "Patching"}, {"id": "b", "text": "Segmentation"}, {"id": "c", "text": "Encryption"}, {"id": "d", "text": "Deterrent signage"}], "answer": "b", "why": "Segmentation contains lateral movement."}, {"type": "callout", "variant": "info", "text": "When you''re ready, head to the Domain Checkpoint: fresh scenarios from all eight lessons in this domain."}]'::jsonb where id = '1c7d7819-3a0b-4bd8-b871-c179bb8562d4';

-- Architecture Models: Cloud, IaC, Serverless, and Microservices
update lessons set content_blocks = '[{"text": "Architecture Models: Cloud, IaC, Serverless, and Microservices", "type": "title", "overview": "The modern architecture patterns organizations use, and the specific security implications each one introduces.", "examContext": "Frequently tested via the shared responsibility model, who (cloud provider vs. customer) is responsible for securing what."}, {"type": "diagram", "heading": "Shared responsibility by service model", "diagram": {"kind": "pyramid", "tiers": [{"label": "SaaS", "note": "Customer secures its data and user access. Provider runs the rest."}, {"label": "PaaS", "note": "Customer also secures its application code and configuration."}, {"label": "IaaS", "note": "Customer also secures operating systems, middleware and network settings."}, {"label": "On premises", "note": "Customer secures everything.", "muted": true}], "top": "provider does the most", "bottom": "customer does the most"}, "caption": "The provider secures the infrastructure; the customer secures what it configures and puts on top. The line moves as you go from IaaS to SaaS."}, {"type": "term_set", "heading": "Modern architecture patterns", "terms": [{"term": "Infrastructure as Code (IaC)", "short": "Infrastructure defined in version-controlled files. Consistent, but one flawed template spreads its flaw everywhere."}, {"term": "Serverless", "short": "Short-lived, event-triggered functions on servers the provider manages. Security focus shifts to code and permissions."}, {"term": "Microservices", "short": "Small, independently deployed services. More flexible, but many more network interfaces to secure."}, {"term": "Containerization", "short": "An app packaged with its dependencies in an isolated unit. Container escape breaks that isolation."}]}, {"type": "key_term", "term": "IaC risk", "definition": "Automation replicates mistakes as faithfully as good configuration.", "example": "A Terraform module with an open security group is reused by twelve teams, and the same exposure appears in every environment overnight."}, {"type": "scenario", "prompt": "A company runs its own operating systems and applications on virtual machines it rents from a cloud provider. Who patches the operating systems?", "choices": [{"id": "a", "text": "The cloud provider"}, {"id": "b", "text": "The customer"}, {"id": "c", "text": "Both equally"}, {"id": "d", "text": "Nobody; it''s automatic"}], "answer": "b", "why": "In IaaS, the customer is responsible from the operating system up."}, {"type": "scenario", "prompt": "What new risk comes with breaking one large application into dozens of microservices?", "choices": [{"id": "a", "text": "Fewer deployment options"}, {"id": "b", "text": "Many more network-exposed interfaces to secure"}, {"id": "c", "text": "No way to scale"}, {"id": "d", "text": "Loss of version control"}], "answer": "b", "why": "Each service talks over the network, multiplying the interfaces that need authentication and protection."}, {"type": "callout", "variant": "tip", "text": "IaaS: customer secures the OS and up. SaaS: customer secures data and access. IaC repeats whatever you give it, good or bad."}]'::jsonb where id = '687e307c-beb5-405e-a872-518e67b97ff9';

-- On-Premises, Centralized/Decentralized, and IoT/ICS/SCADA Architecture
update lessons set content_blocks = '[{"text": "On-Premises, Centralized/Decentralized, and IoT/ICS/SCADA Architecture", "type": "title", "overview": "Architecture choices outside the cloud, traditional on-premises infrastructure, the centralized/decentralized tradeoff, and the specialized world of operational technology.", "examContext": "IoT/ICS/SCADA questions often hinge on the fact that these systems prioritize availability and uptime over patching speed."}, {"type": "compare", "heading": "On-premises vs. hybrid", "columns": ["On-premises", "Hybrid"], "rows": [{"label": "Control", "values": ["Full control and full responsibility", "Split between local and cloud"]}, {"label": "Typical reason", "values": ["Strict control or regulation", "Keep sensitive workloads local, use the cloud for scale"]}]}, {"type": "compare", "heading": "Centralized vs. decentralized", "columns": ["Centralized", "Decentralized"], "rows": [{"label": "Computing and decisions", "values": ["In one place", "Spread across independent nodes"]}, {"label": "Strength", "values": ["Simpler to secure and manage", "Survives a single failure"]}, {"label": "Weakness", "values": ["Single point of failure", "Harder to secure and monitor consistently"]}]}, {"type": "term_set", "heading": "Operational technology", "terms": [{"term": "IoT", "short": "Networked everyday devices, often with weak defaults and rare patches."}, {"term": "ICS", "short": "Industrial control systems running physical processes. Safety and uptime first; legacy software."}, {"term": "SCADA", "short": "A kind of ICS for geographically spread infrastructure such as power grids and water systems."}]}, {"type": "key_term", "term": "When you can''t just patch", "definition": "ICS and SCADA systems often can''t be taken offline. The exam expects compensating controls instead.", "example": "A water plant''s controller runs an unsupported OS. The utility isolates it on its own segment with strict firewall rules and monitors its traffic, rather than shutting down treatment to upgrade."}, {"type": "scenario", "prompt": "A vulnerable controller runs an assembly line and can''t be taken offline to patch for six months. What should the security team recommend?", "choices": [{"id": "a", "text": "Patch it immediately anyway"}, {"id": "b", "text": "Segment it and monitor it closely as compensating controls"}, {"id": "c", "text": "Ignore the vulnerability"}, {"id": "d", "text": "Replace it with a cloud service"}], "answer": "b", "why": "For ICS, uptime and safety come first, so compensating controls such as segmentation and monitoring are the expected answer."}, {"type": "scenario", "prompt": "Which architecture is easiest to manage consistently but creates a single point of failure?", "choices": [{"id": "a", "text": "Decentralized"}, {"id": "b", "text": "Centralized"}, {"id": "c", "text": "Peer-to-peer"}, {"id": "d", "text": "Hybrid"}], "answer": "b", "why": "Everything in one place is simpler and also fragile."}, {"type": "callout", "variant": "tip", "text": "ICS and SCADA put uptime and safety first: segment and monitor instead of \"just patch it\". Centralized is simpler; decentralized is more resilient."}]'::jsonb where id = '137c5a8c-66d7-42a8-9c0e-7df7a1ab013f';

-- Securing Enterprise Infrastructure
update lessons set content_blocks = '[{"text": "Securing Enterprise Infrastructure", "type": "title", "overview": "How network devices are placed, configured, and connected to enforce security boundaries across an enterprise network.", "examContext": "Frequently tested through scenario questions about where a device sits in the network and what that placement implies."}, {"type": "term_set", "heading": "Placement and behavior", "terms": [{"term": "Screened subnet (DMZ)", "short": "A buffer zone for public-facing services that shields the internal network."}, {"term": "Attack surface", "short": "Kept small by putting only necessary services in exposed zones."}, {"term": "Fail-open", "short": "Lets traffic through when the device fails: availability first."}, {"term": "Fail-closed", "short": "Blocks traffic when the device fails: security first."}]}, {"type": "compare", "heading": "Inline vs. tap / monitor", "columns": ["Inline (active)", "Tap or monitor port (passive)"], "rows": [{"label": "Sees", "values": ["The real traffic, in the path", "A copy of the traffic"]}, {"label": "Can block?", "values": ["Yes", "No, only alert"]}, {"label": "Example", "values": ["IPS", "IDS"]}, {"label": "Risk", "values": ["Can disrupt traffic if it fails or misfires", "Can''t stop an attack in progress"]}]}, {"type": "term_set", "heading": "Devices and connections", "terms": [{"term": "NGFW", "short": "Firewall with application awareness, intrusion prevention and threat intelligence."}, {"term": "IDS / IPS", "short": "Alerts only / sits inline and blocks."}, {"term": "SD-WAN", "short": "Centrally steers traffic across MPLS, broadband and LTE by policy and performance."}, {"term": "VPN", "short": "Encrypted tunnel across an untrusted network for remote access or site links."}]}, {"type": "scenario", "prompt": "An intrusion device receives a copy of traffic from a switch''s monitor port. What can it do when it sees an attack?", "choices": [{"id": "a", "text": "Block the traffic"}, {"id": "b", "text": "Alert only"}, {"id": "c", "text": "Reroute the traffic"}, {"id": "d", "text": "Quarantine the host automatically"}], "answer": "b", "why": "A device on a tap or monitor port is passive: it sees a copy and can only alert."}, {"type": "scenario", "prompt": "A hospital wants its web filter to keep passing traffic if the filter itself fails, so clinical systems stay reachable. Which behavior is this?", "choices": [{"id": "a", "text": "Fail-closed"}, {"id": "b", "text": "Fail-open"}, {"id": "c", "text": "Fail-secure"}, {"id": "d", "text": "Fail-over"}], "answer": "b", "why": "Letting traffic through on failure prioritizes availability: fail-open."}, {"type": "callout", "variant": "tip", "text": "Inline can block; a tap can only watch. Fail-open favors availability; fail-closed favors security."}]'::jsonb where id = 'dcd0c75d-35ac-4068-a2b3-739ec8557c3f';

-- Data Protection Strategies
update lessons set content_blocks = '[{"text": "Data Protection Strategies", "type": "title", "overview": "Categorizing data by sensitivity and type, understanding where data lives, and the specific methods used to protect it in each state.", "examContext": "Expect questions distinguishing the three data states, and questions matching a data protection method to a specific scenario."}, {"type": "diagram", "heading": "Data classification levels", "diagram": {"kind": "ladder", "rungs": [{"label": "Confidential / restricted", "note": "Serious harm if disclosed; access tightly limited."}, {"label": "Sensitive", "note": "Harm if disclosed: financial, regulated or trade secret data."}, {"label": "Private / internal", "note": "Not for release, limited harm."}, {"label": "Public", "note": "Freely shareable."}], "top": "most sensitive", "bottom": "least"}, "caption": "Separately, **critical** data is essential to core operations and gets priority in recovery."}, {"type": "compare", "heading": "Three data states", "columns": ["At rest", "In transit", "In use"], "rows": [{"label": "Where", "values": ["Disks, databases, backups", "Moving across a network", "Being processed in memory"]}, {"label": "Main protection", "values": ["Encryption at rest, access controls", "TLS, IPsec", "Secure enclaves, memory encryption"]}, {"label": "Difficulty", "values": ["Well understood", "Well understood", "Hardest"]}]}, {"type": "key_term", "term": "Data sovereignty", "definition": "Data is subject to the laws of the country where it''s physically stored or processed. A major driver of where cloud data may live.", "example": "A German healthcare provider requires its cloud provider to keep patient data in EU regions only."}, {"type": "term_set", "heading": "Protection methods", "terms": [{"term": "Geographic restrictions", "short": "Keep data inside approved jurisdictions."}, {"term": "Encryption / hashing", "short": "Confidentiality / integrity."}, {"term": "Masking / tokenization / obfuscation", "short": "Hide or replace sensitive values."}, {"term": "Segmentation / permission restrictions", "short": "Limit where data lives and who reaches it."}]}, {"type": "scenario", "prompt": "A company encrypts its database files on disk and uses TLS for connections. What state of data is still unprotected by these two controls?", "choices": [{"id": "a", "text": "At rest"}, {"id": "b", "text": "In transit"}, {"id": "c", "text": "In use"}, {"id": "d", "text": "None"}], "answer": "c", "why": "Neither disk encryption nor TLS protects data while it''s decrypted in memory for processing."}, {"type": "scenario", "prompt": "An EU regulator requires that citizens'' records never be stored outside the EU. Which concept drives this?", "choices": [{"id": "a", "text": "Data masking"}, {"id": "b", "text": "Data sovereignty"}, {"id": "c", "text": "Data classification"}, {"id": "d", "text": "Tokenization"}], "answer": "b", "why": "Data is bound by the laws of where it''s stored."}, {"type": "callout", "variant": "tip", "text": "Match the protection to the state: at rest, in transit, in use. Data sovereignty follows the data''s physical location."}]'::jsonb where id = '75ac7ee2-d6a3-48c7-b540-aebacb98ce5f';

-- Resilience and Recovery in Security Architecture
update lessons set content_blocks = '[{"text": "Resilience and Recovery in Security Architecture", "type": "title", "overview": "Building infrastructure that survives failure, and the recovery site strategies organizations use to keep operating through a disaster.", "examContext": "Expect a direct match-the-site-type-to-the-recovery-time question, plus scenario questions on load balancing and capacity planning."}, {"type": "term_set", "heading": "Building for failure", "terms": [{"term": "High availability", "short": "Redundancy so no single failure takes the service down."}, {"term": "Load balancing", "short": "Spreads traffic across servers and survives one failing."}, {"term": "Clustering", "short": "Servers working as one, with failover between nodes."}, {"term": "Geographic dispersion", "short": "Resources far apart so one regional disaster can''t take everything."}, {"term": "Platform diversity / multi-cloud", "short": "Different vendors or providers so one outage or flaw isn''t fatal."}, {"term": "Capacity planning", "short": "Enough people, technology and infrastructure, including during recovery."}]}, {"type": "compare", "heading": "Recovery sites", "columns": ["Hot", "Warm", "Cold"], "rows": [{"label": "Ready", "values": ["Fully equipped and running", "Some hardware and data ready", "Power and space only"]}, {"label": "Recovery speed", "values": ["Fastest", "Medium", "Slowest"]}, {"label": "Cost", "values": ["Highest", "Medium", "Lowest"]}]}, {"type": "diagram", "heading": "Testing recovery plans", "diagram": {"kind": "ladder", "rungs": [{"label": "Failover test", "note": "Actually shift operations to the backup."}, {"label": "Parallel processing", "note": "Run the recovery site alongside production."}, {"label": "Simulation", "note": "Hands-on scenario without full failover."}, {"label": "Tabletop exercise", "note": "Discussion only; no systems touched."}], "top": "most realistic", "bottom": "least"}}, {"type": "scenario", "prompt": "A business needs to resume operations within minutes of losing its primary data center, and budget isn''t a constraint. Which site fits?", "choices": [{"id": "a", "text": "Cold site"}, {"id": "b", "text": "Warm site"}, {"id": "c", "text": "Hot site"}, {"id": "d", "text": "Tabletop exercise"}], "answer": "c", "why": "Only a hot site can take over almost immediately."}, {"type": "scenario", "prompt": "A team runs its recovery environment alongside production on real data, without cutting over. Which test is this?", "choices": [{"id": "a", "text": "Tabletop"}, {"id": "b", "text": "Simulation"}, {"id": "c", "text": "Parallel processing"}, {"id": "d", "text": "Failover"}], "answer": "c", "why": "Running alongside production without switching is parallel processing."}, {"type": "callout", "variant": "tip", "text": "Hot = fastest and priciest; cold = slowest and cheapest. Tabletop talks; failover actually switches."}]'::jsonb where id = 'c757b2cc-f4f2-4334-8319-3fad2dbbf9ed';

-- Domain 3 Recap
update lessons set content_blocks = '[{"text": "Domain 3 Recap: Security Architecture", "type": "title", "overview": "A condensed pass over architecture models, on-prem/IoT/ICS/SCADA, securing infrastructure, data protection, and resilience/recovery.", "examContext": "This recap has no questions of its own; the Domain Checkpoint right after it draws fresh scenario questions from everything across all 5 lessons."}, {"type": "term_set", "heading": "Architecture", "terms": [{"term": "Shared responsibility", "short": "IaaS: customer from the OS up. SaaS: customer data and access."}, {"term": "IaC", "short": "Consistent and versioned, but replicates flaws."}, {"term": "Microservices / serverless / containers", "short": "More interfaces / code and permissions focus / watch for escape."}, {"term": "ICS and SCADA", "short": "Uptime and safety first; compensating controls."}, {"term": "Centralized / decentralized", "short": "Simpler / more resilient."}]}, {"type": "term_set", "heading": "Infrastructure and data", "terms": [{"term": "Inline / tap", "short": "Can block (IPS) / alert only (IDS)."}, {"term": "Fail-open / fail-closed", "short": "Availability first / security first."}, {"term": "Screened subnet", "short": "Shields the internal network from public services."}, {"term": "Data states", "short": "At rest, in transit, in use (hardest)."}, {"term": "Data sovereignty", "short": "Bound by the laws of where it''s stored."}]}, {"type": "term_set", "heading": "Resilience", "terms": [{"term": "Hot / warm / cold", "short": "Fastest and priciest to slowest and cheapest."}, {"term": "Load balancing and clustering", "short": "Spread load and fail over."}, {"term": "Multi-cloud and platform diversity", "short": "Avoid single-vendor failure."}, {"term": "Tests", "short": "Tabletop, simulation, parallel, failover."}]}, {"type": "scenario", "prompt": "Which device can stop malicious traffic in real time?", "choices": [{"id": "a", "text": "IDS on a tap"}, {"id": "b", "text": "Inline IPS"}, {"id": "c", "text": "NetFlow collector"}, {"id": "d", "text": "SIEM"}], "answer": "b", "why": "Only inline devices can block."}, {"type": "scenario", "prompt": "Which data state is hardest to protect?", "choices": [{"id": "a", "text": "At rest"}, {"id": "b", "text": "In transit"}, {"id": "c", "text": "In use"}, {"id": "d", "text": "Archived"}], "answer": "c", "why": "It must be decrypted to be processed."}, {"type": "scenario", "prompt": "Which recovery site is cheapest but slowest?", "choices": [{"id": "a", "text": "Hot"}, {"id": "b", "text": "Warm"}, {"id": "c", "text": "Cold"}, {"id": "d", "text": "Mobile"}], "answer": "c", "why": "Cold sites have power and space only."}, {"type": "callout", "variant": "info", "text": "When you''re ready, head to the Domain Checkpoint: fresh scenarios from all five lessons in this domain."}]'::jsonb where id = 'dde2456e-814e-43c5-8efb-7d839d35ff46';

-- Security Techniques for Computing Resources
update lessons set content_blocks = '[{"text": "Security Techniques for Computing Resources", "type": "title", "overview": "How organizations establish a secure starting point for systems, harden specific device types, secure wireless networks, manage mobile devices, and build security into applications.", "examContext": "Frequently tested through matching a hardening technique or mobile deployment model to a scenario description."}, {"type": "term_set", "heading": "Key terms at a glance", "terms": [{"term": "Secure baseline", "short": "The documented minimum configuration every system starts from before deployment."}, {"term": "Hardening", "short": "Shrinking the attack surface: disable unneeded services, close unused ports, remove default accounts."}, {"term": "WPA3", "short": "Current Wi-Fi security; resists offline dictionary attacks on the handshake."}, {"term": "MDM", "short": "Enforces policy, encryption and remote wipe on enrolled mobile devices."}, {"term": "Sandboxing", "short": "Runs untrusted code in isolation so any damage stays contained."}]}, {"type": "key_term", "term": "Secure baseline", "definition": "A documented, minimum security configuration applied consistently before a system goes live. Hardening builds on top of it.", "example": "Every new Windows server is built from a gold image with the CIS benchmark settings already applied, so no server starts life with defaults."}, {"type": "key_term", "term": "Hardening", "definition": "Reducing attack surface on every device type: workstations, servers, switches, routers, cloud, ICS, embedded systems and IoT alike.", "example": "A new switch ships with Telnet and a default admin account. Hardening disables Telnet, enables SSH and removes or renames the default account."}, {"type": "compare", "heading": "Mobile deployment models", "columns": ["BYOD", "COPE", "CYOD"], "rows": [{"label": "Who owns the device", "values": ["Employee", "Company", "Company, usually"]}, {"label": "Personal use", "values": ["Yes, it''s theirs", "Allowed", "Allowed"]}, {"label": "Company control", "values": ["Least", "Most", "High"]}, {"label": "Device choice", "values": ["Anything the employee owns", "Company issues it", "Employee picks from an approved list"]}], "cue": ["\"Personal phone\"", "\"Company-owned, personal use allowed\"", "\"Choose from a list\""], "intro": "MDM can manage any of the three. The question is always who owns the device."}, {"type": "term_set", "heading": "Application security techniques", "terms": [{"term": "Input validation", "short": "Reject malformed or malicious input before it''s processed."}, {"term": "Secure cookies", "short": "HttpOnly and Secure flags keep cookies away from scripts and plain HTTP."}, {"term": "Static / dynamic analysis", "short": "Review code without running it / test it while it runs."}, {"term": "Code signing", "short": "Proves who published the code and that it hasn''t changed."}, {"term": "Allow list / deny list", "short": "Only approved software runs / known-bad software is blocked."}]}, {"type": "scenario", "prompt": "A company buys phones for its sales team and lets staff install personal apps and use them on weekends. Which deployment model is this?", "choices": [{"id": "a", "text": "BYOD"}, {"id": "b", "text": "COPE"}, {"id": "c", "text": "CYOD"}, {"id": "d", "text": "VDI"}], "answer": "b", "why": "The company owns the device and allows personal use: corporate-owned, personally enabled.", "trap": "CYOD is tempting, but nothing says employees chose from an approved list. Look for who owns it and whether there was a choice."}, {"type": "scenario", "prompt": "An analyst wants to open a suspicious email attachment to see what it does without risking the workstation. What should she use?", "choices": [{"id": "a", "text": "Code signing"}, {"id": "b", "text": "A sandbox"}, {"id": "c", "text": "An allow list"}, {"id": "d", "text": "Static analysis"}], "answer": "b", "why": "A sandbox runs the file in isolation so any malicious behavior is contained."}, {"type": "callout", "variant": "tip", "text": "Read for ownership: employee owns it is BYOD, company owns it with personal use is COPE, picked from a list is CYOD."}]'::jsonb where id = '3286eb04-6d8b-4542-9c46-e1a612163393';

-- Asset Management
update lessons set content_blocks = '[{"text": "Asset Management", "type": "title", "overview": "The security implications of tracking hardware, software, and data through their entire lifecycle, from acquisition through disposal.", "examContext": "Expect questions on matching a sanitization method to a scenario, and on why untracked assets are a security risk."}, {"type": "diagram", "heading": "The asset lifecycle", "diagram": {"kind": "flow", "steps": [{"label": "Acquisition", "note": "Vet vendors and supply chain before buying."}, {"label": "Assignment", "note": "Record owner, classification and inventory (asset tags, CMDB)."}, {"label": "Monitoring", "note": "Keep the inventory current as assets move or change purpose."}, {"label": "Disposal", "note": "Remove from service and sanitize the data it held."}]}, "caption": "A forgotten, untracked asset is usually the least patched and most vulnerable one on the network."}, {"type": "diagram", "heading": "Sanitization methods", "diagram": {"kind": "ladder", "rungs": [{"label": "Destroy", "note": "Shred, incinerate or pulverize. The media is never usable again."}, {"label": "Purge", "note": "Degaussing or cryptographic erase. Defeats lab-grade forensic recovery; media can be reused."}, {"label": "Clear", "note": "Overwrite with standard commands. Stops simple recovery only."}], "top": "strongest", "bottom": "lightest"}}, {"type": "key_term", "term": "Certificate of destruction", "definition": "Documented proof from a disposal vendor that specific media was destroyed to a defined standard. Often required for compliance and audit trails.", "example": "A hospital ships 200 retired drives to a shredding vendor and files the certificate listing each serial number with its audit records."}, {"type": "key_term", "term": "Data retention", "definition": "How long data must be kept before it can be disposed of. It balances legal requirements against the risk of holding data longer than needed.", "example": "Tax records are kept for seven years as required, then securely purged instead of sitting on a file share forever."}, {"type": "scenario", "prompt": "Laptops are being returned to a leasing company and must not reveal any data, even to a forensic lab. The laptops will be reused. Which method fits?", "choices": [{"id": "a", "text": "Clear"}, {"id": "b", "text": "Purge"}, {"id": "c", "text": "Destroy"}, {"id": "d", "text": "Format"}], "answer": "b", "why": "Purge defeats advanced forensic recovery while leaving the media usable.", "trap": "Destroy also defeats forensics, but the leasing company needs the hardware back intact."}, {"type": "scenario", "prompt": "A vulnerability scan keeps finding an unpatched server nobody on the team recognizes. What process failure most likely caused this?", "choices": [{"id": "a", "text": "Poor data retention"}, {"id": "b", "text": "Gaps in asset tracking and inventory"}, {"id": "c", "text": "Weak sanitization"}, {"id": "d", "text": "Missing code signing"}], "answer": "b", "why": "Assets that aren''t tracked don''t get patched. Accurate inventory is the foundation of vulnerability management."}, {"type": "callout", "variant": "tip", "text": "Clear for everyday reuse, purge when forensics must fail but the media lives on, destroy when the media itself must die."}]'::jsonb where id = '6e439bb5-fc14-48ca-809a-f1c683425181';

-- Vulnerability Management
update lessons set content_blocks = '[{"text": "Vulnerability Management", "type": "title", "overview": "The full cycle of finding, scoring, fixing, and confirming the fix for vulnerabilities across an organization''s systems.", "examContext": "One of the most heavily tested topics in this domain, expect scenario questions on prioritization, false positives, and choosing the right remediation option."}, {"type": "diagram", "heading": "The vulnerability management cycle", "diagram": {"kind": "cycle", "steps": [{"label": "Identify", "note": "Scans, threat feeds, pen tests, bug bounties, audits."}, {"label": "Analyze", "note": "Confirm it''s real and score it."}, {"label": "Prioritize", "note": "CVSS plus exposure, environment and impact."}, {"label": "Remediate", "note": "Patch, segment, insure or formally except."}, {"label": "Validate", "note": "Rescan or audit to prove the fix worked, then report."}], "center": "continuous"}}, {"type": "term_set", "heading": "Where vulnerabilities are found", "terms": [{"term": "Vulnerability scan", "short": "Automated check of networks and apps against known signatures."}, {"term": "Threat feed", "short": "OSINT, commercial feeds or an ISAC; the dark web is watched for leaks."}, {"term": "Penetration test", "short": "Authorized, simulated attack to find exploitable weaknesses."}, {"term": "Bug bounty / responsible disclosure", "short": "Outside researchers report flaws, often for a reward."}, {"term": "System or process audit", "short": "Formal review of configurations and procedures against a standard."}]}, {"type": "key_term", "term": "CVE", "definition": "A standard identifier for one specific, publicly known vulnerability, so every tool and team means the same flaw.", "example": "Your scanner, the vendor advisory and a news article all reference CVE-2021-44228, so everyone knows it''s Log4Shell."}, {"type": "key_term", "term": "CVSS", "definition": "A standard 0 to 10 severity score used to prioritize. Higher means more urgent, but it''s a starting point, not the whole answer.", "example": "A 9.8 on an isolated lab box may be less urgent than a 7.5 on an internet-facing payment server."}, {"type": "compare", "heading": "False positive vs. false negative", "columns": ["False positive", "False negative"], "rows": [{"label": "What happened", "values": ["Flags a vulnerability that isn''t there", "Misses one that is"]}, {"label": "Cost", "values": ["Wasted investigation time", "Real, unaddressed risk"]}, {"label": "Which is worse", "values": ["Less serious", "More serious"]}]}, {"type": "term_set", "heading": "Remediation options", "terms": [{"term": "Patch", "short": "The direct fix, when one exists."}, {"term": "Segmentation / compensating controls", "short": "Reduce exposure when patching isn''t possible yet."}, {"term": "Insurance", "short": "Transfer the financial impact of what remains."}, {"term": "Exception / exemption", "short": "A documented, time-bound decision to accept the risk for now."}, {"term": "Validation", "short": "Rescan, audit or verify independently that the fix worked."}]}, {"type": "scenario", "prompt": "A scanner reports a critical flaw on a server, but investigation shows the vulnerable package isn''t installed. What is this?", "choices": [{"id": "a", "text": "True positive"}, {"id": "b", "text": "False positive"}, {"id": "c", "text": "False negative"}, {"id": "d", "text": "True negative"}], "answer": "b", "why": "The tool flagged something that isn''t actually there."}, {"type": "scenario", "prompt": "Two vulnerabilities have the same CVSS score. One is on an internet-facing customer portal; the other is on an isolated test server. How should they be prioritized?", "choices": [{"id": "a", "text": "Equally, since the scores match"}, {"id": "b", "text": "The portal first, because of exposure and business impact"}, {"id": "c", "text": "The test server first"}, {"id": "d", "text": "Neither until a patch exists"}], "answer": "b", "why": "Prioritization weighs exposure, environment and organizational impact on top of the raw score.", "trap": "Treating CVSS as the whole answer is the trap. The exam wants context."}, {"type": "callout", "variant": "tip", "text": "Patching isn''t the last step: always validate with a rescan. And a missed real flaw (false negative) beats a false alarm in seriousness."}]'::jsonb where id = '3e2f6319-7109-4738-a3d7-be36b5e68115';

-- Security Alerting and Monitoring
update lessons set content_blocks = '[{"text": "Security Alerting and Monitoring", "type": "title", "overview": "The activities and tools organizations use to continuously watch computing resources and respond when something looks wrong.", "examContext": "Expect questions matching a monitoring tool or activity to its purpose, especially SIEM and alert tuning scenarios."}, {"type": "diagram", "heading": "From logs to action", "diagram": {"kind": "flow", "steps": [{"label": "Aggregate", "note": "Collect logs from many sources in one place."}, {"label": "Correlate and alert", "note": "Spot patterns and notify staff."}, {"label": "Respond", "note": "Act on the real alerts."}, {"label": "Tune", "note": "Adjust rules and thresholds to cut noise."}, {"label": "Archive and report", "note": "Keep logs for investigation and compliance; summarize for stakeholders."}]}}, {"type": "key_term", "term": "SIEM", "definition": "Security information and event management: aggregates logs and events across the environment, correlates them and raises alerts. The hub of most enterprise monitoring.", "example": "The SIEM links five failed VPN logins, a success from a new country and a large file download into one high-priority alert."}, {"type": "key_term", "term": "SCAP", "definition": "Security Content Automation Protocol: standard specifications for automating vulnerability checks and compliance measurement against benchmarks.", "example": "A scanner uses SCAP content to check 500 servers against the same hardening benchmark and produce a comparable report."}, {"type": "compare", "heading": "Agent-based vs. agentless monitoring", "columns": ["Agent-based", "Agentless"], "rows": [{"label": "How", "values": ["Software installed on the host", "Watches from outside the host"]}, {"label": "Visibility", "values": ["Deep", "Often less detailed"]}, {"label": "Deployment", "values": ["More effort", "Easier"]}]}, {"type": "term_set", "heading": "Other monitoring tools", "terms": [{"term": "NetFlow", "short": "Summarized traffic metadata: who talked to whom, how much."}, {"term": "SNMP traps", "short": "Network devices push alert conditions to a manager."}, {"term": "Antivirus", "short": "Detects known malware on hosts."}, {"term": "DLP", "short": "Watches for sensitive data leaving improperly."}, {"term": "Vulnerability scanner", "short": "Finds known weaknesses on a schedule."}]}, {"type": "scenario", "prompt": "Analysts receive thousands of low-value alerts a day and are missing real incidents buried among them. What should the team do?", "choices": [{"id": "a", "text": "Disable the noisiest rules entirely"}, {"id": "b", "text": "Tune alert thresholds and rules"}, {"id": "c", "text": "Hire more analysts to read every alert"}, {"id": "d", "text": "Turn off the SIEM"}], "answer": "b", "why": "Tuning reduces false positives while keeping real detection in place.", "trap": "Disabling rules removes noise and detection with it."}, {"type": "scenario", "prompt": "A network team wants to see which internal hosts are sending unusually large volumes of traffic to the internet, without capturing full packets. Which tool fits?", "choices": [{"id": "a", "text": "SNMP traps"}, {"id": "b", "text": "NetFlow"}, {"id": "c", "text": "Antivirus"}, {"id": "d", "text": "SCAP"}], "answer": "b", "why": "NetFlow summarizes flows: source, destination and volume."}, {"type": "callout", "variant": "tip", "text": "Too many alerts? Tune, don''t disable. SIEM aggregates and correlates; NetFlow summarizes traffic; SCAP automates compliance checks."}]'::jsonb where id = 'd4607f49-01f9-439f-a176-100faebbe458';

-- Enterprise Security Capabilities I: Network and Perimeter Defenses
update lessons set content_blocks = '[{"text": "Enterprise Security Capabilities I: Network and Perimeter Defenses", "type": "title", "overview": "The capabilities enterprises deploy at the network perimeter and beyond to inspect, filter, and control traffic.", "examContext": "Expect questions distinguishing firewall types and IDS/IPS detection methods, plus scenario-based secure protocol selection."}, {"type": "term_set", "heading": "Firewall types", "terms": [{"term": "Layer 4 firewall", "short": "Filters on IP address, port and protocol only."}, {"term": "NGFW (layer 7)", "short": "Adds application awareness, deep packet inspection and often IPS."}, {"term": "WAF", "short": "Protects web applications from attacks like SQL injection and XSS."}, {"term": "UTM", "short": "One appliance combining firewall, antivirus, IPS and content filtering."}]}, {"type": "compare", "heading": "WAF vs. NGFW", "columns": ["WAF", "NGFW"], "rows": [{"label": "Protects", "values": ["Web applications", "The whole network"]}, {"label": "Traffic", "values": ["HTTP and HTTPS", "All traffic, with application awareness"]}, {"label": "Stops", "values": ["SQL injection, XSS, other web attacks", "Unwanted apps, intrusions, policy violations"]}], "cue": ["\"Web app\" or \"SQL injection\"", "\"Application awareness\" across the network"]}, {"type": "compare", "heading": "IDS / IPS detection methods", "columns": ["Signature-based", "Anomaly (trend) based"], "rows": [{"label": "How", "values": ["Matches known attack patterns", "Flags deviations from a learned baseline"]}, {"label": "Catches new attacks?", "values": ["No", "Yes"]}, {"label": "False positives", "values": ["Fewer", "More"]}]}, {"type": "key_term", "term": "DNS filtering", "definition": "Blocks known malicious or unwanted domains when the name is looked up, so the connection never starts.", "example": "A user clicks a phishing link; the DNS resolver refuses to resolve the domain and the browser shows a block page instead."}, {"type": "key_term", "term": "Web filtering", "definition": "Controls what web content users reach, through an agent on each endpoint or a central proxy, using URL categories, block rules and reputation.", "example": "Remote laptops run a filtering agent so policy applies at home as well as in the office proxy."}, {"type": "compare", "heading": "Choose the secure protocol", "columns": ["Insecure", "Secure replacement"], "rows": [{"label": "Web", "values": ["HTTP (80)", "HTTPS (443)"]}, {"label": "File transfer", "values": ["FTP (21)", "SFTP (22) or FTPS"]}, {"label": "Remote shell", "values": ["Telnet (23)", "SSH (22)"]}]}, {"type": "scenario", "prompt": "An online store keeps getting hit with SQL injection attempts against its checkout page. Which control is designed for this?", "choices": [{"id": "a", "text": "Layer 4 firewall"}, {"id": "b", "text": "WAF"}, {"id": "c", "text": "DNS filter"}, {"id": "d", "text": "UTM"}], "answer": "b", "why": "A WAF inspects HTTP traffic for web application attacks like SQL injection.", "trap": "An NGFW or UTM might help, but when the scenario names a web app attack, the WAF is the specific answer."}, {"type": "scenario", "prompt": "A security team needs to detect a brand-new attack technique that has no published signature. Which detection method has the best chance?", "choices": [{"id": "a", "text": "Signature-based"}, {"id": "b", "text": "Anomaly-based"}, {"id": "c", "text": "Port-based filtering"}, {"id": "d", "text": "DNS filtering"}], "answer": "b", "why": "Only anomaly detection can flag something it has never seen before."}, {"type": "callout", "variant": "tip", "text": "Web app named in the question? WAF. Unknown attack? Anomaly detection. Known attack with few false alarms? Signatures."}]'::jsonb where id = '72da3c0b-f4f7-429c-8be3-536692f6b6bd';

-- Enterprise Security Capabilities II: Endpoint, Email, and Data Protection
update lessons set content_blocks = '[{"text": "Enterprise Security Capabilities II: Endpoint, Email, and Data Protection", "type": "title", "overview": "Enterprise capabilities focused on the endpoint, email, and data layers rather than the network perimeter.", "examContext": "Expect a direct match-the-acronym-to-its-purpose question on DMARC/DKIM/SPF, and a scenario distinguishing EDR from XDR."}, {"type": "diagram", "heading": "Email authentication in three layers", "diagram": {"kind": "flow", "steps": [{"label": "SPF", "note": "Which mail servers may send for this domain."}, {"label": "DKIM", "note": "A signature proving the message wasn''t altered."}, {"label": "DMARC", "note": "What receivers do when SPF or DKIM fails, plus reporting."}]}, "caption": "An email gateway filters spam, phishing and malware before mail reaches the inbox."}, {"type": "term_set", "heading": "Key terms at a glance", "terms": [{"term": "Group Policy / SELinux", "short": "Central Windows configuration / Linux mandatory access control."}, {"term": "FIM", "short": "Hashes critical files and alerts on unauthorized change."}, {"term": "DLP", "short": "Stops sensitive data leaving by email, USB or upload."}, {"term": "NAC", "short": "Checks a device''s posture before letting it on the network."}, {"term": "UEBA", "short": "Baselines normal user behavior and flags anomalies."}]}, {"type": "key_term", "term": "File integrity monitoring (FIM)", "definition": "Continuously compares critical files to a known-good hash baseline and alerts on changes.", "example": "An alert fires when a web server''s login page script changes at 3 a.m. with no change ticket, revealing an injected card skimmer."}, {"type": "key_term", "term": "NAC", "definition": "Enforces policy before a device joins the network: patch level, antivirus status and overall posture.", "example": "A contractor''s laptop with outdated antivirus is placed in a remediation VLAN until it updates."}, {"type": "compare", "heading": "EDR vs. XDR", "columns": ["EDR", "XDR"], "rows": [{"label": "Sees", "values": ["Individual endpoints", "Endpoints plus network, email and cloud"]}, {"label": "Strength", "values": ["Deep host detail and response", "Correlation across layers"]}], "cue": ["\"On the laptop\"", "\"Across endpoint, email and cloud\""]}, {"type": "key_term", "term": "UEBA", "definition": "User and entity behavior analytics: learns normal activity and flags anomalies that suggest a compromised account or insider.", "example": "An accountant who normally opens 20 files a day suddenly downloads 4,000 from the HR share at midnight."}, {"type": "scenario", "prompt": "Customers are receiving emails that appear to come from your domain but were sent by an attacker''s server. Which record tells receivers which servers are allowed to send for you?", "choices": [{"id": "a", "text": "DKIM"}, {"id": "b", "text": "SPF"}, {"id": "c", "text": "DMARC"}, {"id": "d", "text": "MX"}], "answer": "b", "why": "SPF lists the authorized sending servers.", "trap": "DMARC tells receivers what to do on failure, but SPF is the list itself."}, {"type": "scenario", "prompt": "An employee tries to upload a spreadsheet of customer Social Security numbers to a personal cloud drive, and the upload is blocked. Which control did this?", "choices": [{"id": "a", "text": "NAC"}, {"id": "b", "text": "FIM"}, {"id": "c", "text": "DLP"}, {"id": "d", "text": "EDR"}], "answer": "c", "why": "DLP detects sensitive data leaving the organization and blocks it."}, {"type": "callout", "variant": "tip", "text": "SPF says who can send, DKIM proves it wasn''t altered, DMARC says what to do on failure. NAC checks before entry; DLP stops data on the way out."}]'::jsonb where id = 'f9697b09-2475-4d12-acb2-2701af51414d';

-- Identity and Access Management Implementation
update lessons set content_blocks = '[{"text": "Identity and Access Management Implementation", "type": "title", "overview": "How identities are created and retired, how organizations let users authenticate once across multiple systems, the models used to decide who can access what, and how multifactor authentication strengthens the login itself.", "examContext": "One of the highest-yield topics in Domain 4, expect several questions matching an access control model or MFA factor to a scenario."}, {"type": "diagram", "heading": "The identity lifecycle", "diagram": {"kind": "flow", "steps": [{"label": "Identity proofing", "note": "Verify the person is who they claim before creating anything."}, {"label": "Provisioning", "note": "Create the account and access when they join."}, {"label": "Changes", "note": "Adjust access as roles change."}, {"label": "De-provisioning", "note": "Remove access promptly when they leave."}]}, "caption": "Slow de-provisioning is one of the most common real-world gaps."}, {"type": "compare", "heading": "Federation vs. SSO", "columns": ["Federation", "SSO"], "rows": [{"label": "What it does", "values": ["Trusts an identity from another organization or provider", "One login opens many applications"]}, {"label": "Typical protocols", "values": ["SAML, OpenID Connect", "SAML, OAuth, Kerberos, often over LDAP"]}, {"label": "Example", "values": ["Partner staff log in with their own company accounts", "Employees log in once to email, HR and CRM"]}]}, {"type": "compare", "heading": "Access control models", "columns": ["Who or what decides"], "rows": [{"label": "MAC", "values": ["A central authority with labels; users can''t override"]}, {"label": "DAC", "values": ["The resource owner"]}, {"label": "RBAC", "values": ["The user''s job role"]}, {"label": "Rule-based", "values": ["Predefined rules, such as firewall ACLs"]}, {"label": "ABAC", "values": ["Several attributes combined: department, device, time, location"]}], "intro": "Find the decision maker in the scenario and you''ve found the model."}, {"type": "key_term", "term": "Least privilege", "definition": "Grant only the minimum access a job requires. It applies across every model.", "example": "A help desk technician can reset passwords but can''t change domain admin group membership."}, {"type": "diagram", "heading": "MFA factor categories", "diagram": {"kind": "triad", "points": [{"label": "Something you know", "note": "Password, PIN."}, {"label": "Something you have", "note": "Hardware token, smart card, authenticator app."}, {"label": "Something you are", "note": "Fingerprint, face."}], "center": "+ somewhere you are"}, "caption": "True MFA combines different categories. A password and a security question are both something you know, so that''s not MFA."}, {"type": "scenario", "prompt": "Access to a payroll app is allowed only if the user is in Finance, on a managed laptop, during business hours, from the corporate network. Which model is this?", "choices": [{"id": "a", "text": "RBAC"}, {"id": "b", "text": "DAC"}, {"id": "c", "text": "ABAC"}, {"id": "d", "text": "MAC"}], "answer": "c", "why": "Several attributes are evaluated together: attribute-based access control.", "trap": "Finance sounds like a role, but the device, time and location checks make it ABAC."}, {"type": "scenario", "prompt": "A login requires a password and then a PIN. Why isn''t this true multifactor authentication?", "choices": [{"id": "a", "text": "PINs are too short"}, {"id": "b", "text": "Both are something you know"}, {"id": "c", "text": "It needs biometrics"}, {"id": "d", "text": "It needs a location check"}], "answer": "b", "why": "MFA requires factors from different categories."}, {"type": "callout", "variant": "tip", "text": "Match the decider: central authority is MAC, owner is DAC, role is RBAC, many attributes is ABAC."}]'::jsonb where id = 'd9c082b4-ff04-4e60-8085-0b64e49062bf';

-- Privileged Access Management
update lessons set content_blocks = '[{"text": "Privileged Access Management", "type": "title", "overview": "Why administrative and privileged accounts get special handling, and the specific tools and techniques used to limit how long and how broadly elevated access exists.", "examContext": "Expect questions matching a PAM technique (JIT, vaulting, ephemeral credentials) to the risk it specifically reduces."}, {"type": "paragraph", "text": "Domain admins, root and database admins are the highest-value targets: compromise one and everything downstream falls. **Privileged access management (PAM)** limits how long, how broadly and how visibly elevated access exists."}, {"type": "term_set", "heading": "The three PAM techniques", "terms": [{"term": "Just-in-time (JIT) permissions", "short": "Elevated access granted for a specific window, then revoked automatically."}, {"term": "Credential vaulting", "short": "Privileged passwords live in a vault; checkout is logged and the password rotates after use."}, {"term": "Ephemeral credentials", "short": "Short-lived credentials created for one session or task, useless once expired."}]}, {"type": "key_term", "term": "Just-in-time permissions", "definition": "Removes standing admin rights. Access exists only while the task needs it.", "example": "A DBA requests admin on the production database for a two-hour maintenance window; the rights disappear when the window closes."}, {"type": "key_term", "term": "Credential vaulting", "definition": "Admins check credentials out of a vault rather than knowing them; every checkout is recorded.", "example": "The root password for a firewall is checked out, used, and rotated by the vault so the admin''s copy is now useless."}, {"type": "key_term", "term": "Ephemeral credentials", "definition": "Generated per session and expire on their own, so a leaked one has a very short shelf life.", "example": "A CI pipeline receives cloud credentials valid for 15 minutes for each deployment run."}, {"type": "term_set", "heading": "Password concepts behind it all", "terms": [{"term": "Length and complexity", "short": "Longer passwords resist guessing best."}, {"term": "No reuse", "short": "One breached password shouldn''t open other doors."}, {"term": "Password manager", "short": "Makes unique, strong passwords practical."}, {"term": "Passwordless", "short": "Biometrics, hardware keys or certificates remove the password to steal."}]}, {"type": "scenario", "prompt": "An administrator is granted domain admin rights for the length of an approved change, and they''re removed automatically afterward. Which technique is this?", "choices": [{"id": "a", "text": "Credential vaulting"}, {"id": "b", "text": "Just-in-time permissions"}, {"id": "c", "text": "Ephemeral credentials"}, {"id": "d", "text": "Role-based access"}], "answer": "b", "why": "Time-limited elevation that''s revoked automatically is JIT."}, {"type": "scenario", "prompt": "Admins no longer know the service account passwords; they check them out of a secure system that logs each use and changes the password afterward. Which technique is this?", "choices": [{"id": "a", "text": "JIT"}, {"id": "b", "text": "Vaulting"}, {"id": "c", "text": "Federation"}, {"id": "d", "text": "SSO"}], "answer": "b", "why": "A logged, rotating checkout system is credential vaulting."}, {"type": "callout", "variant": "tip", "text": "Standing admin rights are the risk. Time-limited elevation is JIT, checked-out passwords are vaulting, self-expiring credentials are ephemeral."}]'::jsonb where id = 'ec77eb9d-b968-4b62-83d2-1153226eb9c7';

-- Automation and Orchestration in Security Operations
update lessons set content_blocks = '[{"text": "Automation and Orchestration in Security Operations", "type": "title", "overview": "Why security teams automate repetitive tasks, what that actually buys them, and what it costs when it goes wrong.", "examContext": "Expect a question or two on the downside/considerations side, automation isn''t purely a benefit on this exam."}, {"type": "term_set", "heading": "Common automation use cases", "terms": [{"term": "Provisioning", "short": "Create users and resources at scale."}, {"term": "Guard rails and security groups", "short": "Applied automatically to every new resource."}, {"term": "Ticketing and escalation", "short": "Opened and routed when a condition is met."}, {"term": "Enable or disable access", "short": "Disable an account the moment HR marks someone terminated."}, {"term": "API integrations", "short": "Security tools trigger actions in each other."}]}, {"type": "compare", "heading": "Automation cuts both ways", "columns": ["Benefits", "Considerations"], "rows": [{"label": "Speed", "values": ["Reacts in seconds, not hours", "A bad playbook does harm in seconds too"]}, {"label": "Consistency", "values": ["Enforces baselines every time", "Repeats a flaw every time"]}, {"label": "Scale", "values": ["Grows without growing headcount", "Becomes a single point of failure"]}, {"label": "People", "values": ["Removes toil; helps retention", "Someone must understand and support it"]}, {"label": "Cost", "values": ["Saves analyst time", "Up-front build cost, ongoing upkeep and technical debt"]}]}, {"type": "key_term", "term": "Technical debt", "definition": "Scripts and playbooks that nobody updates as the environment changes, until they break or act wrongly.", "example": "An offboarding script still targets a directory server that was retired last year, so departed staff keep their cloud access."}, {"type": "scenario", "prompt": "An automated playbook meant to quarantine one infected laptop has a bug and isolates every machine in the finance department. Which consideration does this show?", "choices": [{"id": "a", "text": "Workforce multiplier"}, {"id": "b", "text": "Single point of failure"}, {"id": "c", "text": "Employee retention"}, {"id": "d", "text": "Baseline enforcement"}], "answer": "b", "why": "A flawed automated workflow can fail broadly and instantly."}, {"type": "scenario", "prompt": "Which is a benefit of automating account disablement when HR marks an employee as terminated?", "choices": [{"id": "a", "text": "It removes all need for audits"}, {"id": "b", "text": "Faster, consistent reaction with no forgotten accounts"}, {"id": "c", "text": "It eliminates complexity"}, {"id": "d", "text": "It removes technical debt"}], "answer": "b", "why": "Automation reacts immediately and the same way every time."}, {"type": "callout", "variant": "tip", "text": "On the exam, automation is never purely good. Expect complexity, cost, single point of failure and technical debt as valid answers."}]'::jsonb where id = 'ce35f608-e54e-4ffa-b179-b656d4c20109';

-- Incident Response Activities
update lessons set content_blocks = '[{"text": "Incident Response Activities", "type": "title", "overview": "The structured process organizations follow when something goes wrong, and the proactive/reflective activities that surround it.", "examContext": "The incident response process order is one of the most reliably tested sequences in the entire exam, memorize it exactly."}, {"type": "diagram", "heading": "The incident response process", "diagram": {"kind": "flow", "steps": [{"label": "Preparation", "note": "Plans, tools and trained staff, before anything happens."}, {"label": "Detection", "note": "Recognize that an incident is happening."}, {"label": "Analysis", "note": "Scope, root cause and severity."}, {"label": "Containment", "note": "Stop it spreading."}, {"label": "Eradication", "note": "Remove the threat completely."}, {"label": "Recovery", "note": "Restore normal operation."}, {"label": "Lessons learned", "note": "Review and improve the process."}]}, "caption": "Memorize this order exactly. A described activity almost always maps to one step."}, {"type": "compare", "heading": "Containment vs. eradication vs. recovery", "columns": ["Containment", "Eradication", "Recovery"], "rows": [{"label": "Goal", "values": ["Stop the spread", "Remove the threat", "Return to normal"]}, {"label": "Example", "values": ["Isolate the infected host", "Delete malware, close the hole", "Restore from clean backup, monitor"]}], "cue": ["\"Isolate\" or \"disconnect\"", "\"Remove\" or \"wipe\"", "\"Restore\" or \"bring back online\""]}, {"type": "key_term", "term": "Root cause analysis", "definition": "Finding the true underlying cause, not just the symptom, so the gap actually closes.", "example": "Malware is removed, but analysis shows it got in through an unpatched VPN appliance. Patching that appliance is the real fix."}, {"type": "key_term", "term": "Threat hunting", "definition": "Proactively searching for signs of compromise that automated detection missed, rather than waiting for an alert.", "example": "An analyst hypothesizes attackers are using scheduled tasks for persistence and searches every endpoint for unusual ones."}, {"type": "callout", "variant": "info", "text": "Plans are proven through **training** (people know their roles) and **testing**: a **tabletop exercise** talks it through, a **simulation** acts it out. These are the same test types used for disaster recovery."}, {"type": "scenario", "prompt": "An analyst unplugs an infected server from the network so the malware can''t reach other hosts. Which phase is this?", "choices": [{"id": "a", "text": "Detection"}, {"id": "b", "text": "Containment"}, {"id": "c", "text": "Eradication"}, {"id": "d", "text": "Recovery"}], "answer": "b", "why": "Stopping the spread is containment.", "trap": "Eradication comes next: actually removing the malware."}, {"type": "scenario", "prompt": "Two weeks after an incident closes, the team meets to discuss what went well and update the response plan. Which phase is this?", "choices": [{"id": "a", "text": "Preparation"}, {"id": "b", "text": "Analysis"}, {"id": "c", "text": "Recovery"}, {"id": "d", "text": "Lessons learned"}], "answer": "d", "why": "The post-incident review is lessons learned."}, {"type": "callout", "variant": "tip", "text": "Preparation, Detection, Analysis, Containment, Eradication, Recovery, Lessons learned. Say it until it''s automatic."}]'::jsonb where id = 'd8b97078-25dc-491c-917a-000f0659c73d';

-- Data Sources for Security Investigations
update lessons set content_blocks = '[{"text": "Data Sources for Security Investigations", "type": "title", "overview": "The specific logs and data sources an investigator reaches for, and which one actually answers a given question during an investigation.", "examContext": "Almost always tested as a scenario: given a specific investigative question, pick the ONE data source that actually answers it."}, {"type": "compare", "heading": "Pick the data source that answers the question", "columns": ["Answers"], "rows": [{"label": "Firewall logs", "values": ["Was this traffic allowed or blocked, and by which rule?"]}, {"label": "Application logs", "values": ["What errors, transactions or user actions happened in this app?"]}, {"label": "Endpoint logs", "values": ["What processes ran and what files were touched on this device?"]}, {"label": "OS security logs", "values": ["Who logged in, when, and did they use privileges?"]}, {"label": "IDS / IPS logs", "values": ["What was flagged or blocked as malicious, and why?"]}, {"label": "Network logs", "values": ["Which hosts connected to which, across the network?"]}, {"label": "Metadata", "values": ["When was this file created or edited? Where did this email really come from?"]}, {"label": "Packet capture", "values": ["Exactly what was sent over the wire, byte for byte?"]}], "intro": "Investigation questions on the exam are usually one question, one right source."}, {"type": "term_set", "heading": "Other sources", "terms": [{"term": "Vulnerability scans", "short": "Show what weaknesses existed and could have been exploited."}, {"term": "Automated reports", "short": "Pre-built summaries across several systems."}, {"term": "Dashboards", "short": "Real-time visual view of many sources."}]}, {"type": "key_term", "term": "Metadata", "definition": "Data about data: timestamps, email headers, image EXIF. It often reveals what the content itself hides.", "example": "A leaked document''s metadata shows the author''s username and the date it was last edited, narrowing down who leaked it."}, {"type": "key_term", "term": "Packet capture (PCAP)", "definition": "The full, raw traffic. The most detailed network evidence, and the largest.", "example": "To prove exactly what data an attacker exfiltrated over an unencrypted channel, the team reconstructs it from the PCAP."}, {"type": "scenario", "prompt": "An investigator needs to know which account logged into a file server at 2 a.m. last Saturday. Which source answers this?", "choices": [{"id": "a", "text": "Firewall logs"}, {"id": "b", "text": "OS security logs"}, {"id": "c", "text": "Packet capture"}, {"id": "d", "text": "Vulnerability scan"}], "answer": "b", "why": "Authentication events are recorded in the operating system''s security log."}, {"type": "scenario", "prompt": "A team needs to see the exact contents of data transferred to a suspicious IP address. Which source provides this?", "choices": [{"id": "a", "text": "NetFlow"}, {"id": "b", "text": "Firewall logs"}, {"id": "c", "text": "Packet capture"}, {"id": "d", "text": "Dashboard"}], "answer": "c", "why": "Only a packet capture holds the actual payload.", "trap": "NetFlow and firewall logs show that a connection happened, not what was in it."}, {"type": "callout", "variant": "tip", "text": "Who logged in: OS logs. Blocked or allowed: firewall logs. What was sent: packet capture. When and by whom a file was made: metadata."}]'::jsonb where id = '6212c163-038b-452f-8b87-2b534d437f97';

-- Domain 4 Recap
update lessons set content_blocks = '[{"text": "Domain 4 Recap: Security Operations", "type": "title", "overview": "A condensed pass over hardening, asset management, vulnerability management, monitoring, enterprise capabilities, IAM/PAM, automation, incident response, and investigative data sources.", "examContext": "This recap has no questions of its own; the Domain Checkpoint right after it draws fresh scenario questions from everything across all 11 lessons in this domain."}, {"type": "term_set", "heading": "Hardening and assets", "terms": [{"term": "BYOD / COPE / CYOD", "short": "Employee owns / company owns with personal use / choose from a list."}, {"term": "Clear, purge, destroy", "short": "Basic overwrite, defeats forensics, media unusable."}, {"term": "Untracked assets", "short": "Usually the least patched and most vulnerable."}]}, {"type": "term_set", "heading": "Vulnerabilities and monitoring", "terms": [{"term": "False negative", "short": "Worse than a false positive: real risk goes unaddressed."}, {"term": "Prioritization", "short": "CVSS plus exposure, environment and impact."}, {"term": "Remediation", "short": "Patch, segment, insure or formally except, then validate."}, {"term": "SIEM", "short": "Aggregates and correlates; fix noise by tuning."}]}, {"type": "term_set", "heading": "Enterprise capabilities", "terms": [{"term": "SPF / DKIM / DMARC", "short": "Who can send / not altered / what to do on failure."}, {"term": "EDR / XDR", "short": "Endpoint only / correlated across layers."}, {"term": "NAC / DLP", "short": "Checks devices before entry / stops data leaving."}, {"term": "WAF", "short": "Protects web apps from SQL injection and XSS."}]}, {"type": "term_set", "heading": "Identity, automation and response", "terms": [{"term": "MAC / DAC / RBAC / ABAC", "short": "Central authority / owner / role / attributes."}, {"term": "MFA", "short": "Factors from different categories."}, {"term": "JIT / vaulting / ephemeral", "short": "Time-limited / checked out and rotated / self-expiring."}, {"term": "Automation", "short": "Faster and consistent, but complex and a single point of failure."}, {"term": "IR order", "short": "Preparation, detection, analysis, containment, eradication, recovery, lessons learned."}, {"term": "Data sources", "short": "Firewall logs, OS logs, PCAP, metadata: match the question."}]}, {"type": "scenario", "prompt": "An infected host has been isolated. What is the next phase?", "choices": [{"id": "a", "text": "Recovery"}, {"id": "b", "text": "Eradication"}, {"id": "c", "text": "Lessons learned"}, {"id": "d", "text": "Detection"}], "answer": "b", "why": "After containment comes eradication."}, {"type": "scenario", "prompt": "Which access control model lets a document''s owner decide who can read it?", "choices": [{"id": "a", "text": "MAC"}, {"id": "b", "text": "DAC"}, {"id": "c", "text": "RBAC"}, {"id": "d", "text": "ABAC"}], "answer": "b", "why": "The owner decides in discretionary access control."}, {"type": "scenario", "prompt": "Which email standard tells receivers to reject messages that fail SPF and DKIM?", "choices": [{"id": "a", "text": "SPF"}, {"id": "b", "text": "DKIM"}, {"id": "c", "text": "DMARC"}, {"id": "d", "text": "S/MIME"}], "answer": "c", "why": "DMARC sets the failure policy and reporting."}, {"type": "callout", "variant": "info", "text": "When you''re ready, head to the Domain Checkpoint: fresh scenarios from all eleven lessons in this domain."}]'::jsonb where id = '6a6915fd-03ec-4d38-ba7f-b24d5a1f8ab8';

-- Governance Elements
update lessons set content_blocks = '[{"text": "Governance Elements", "type": "title", "overview": "The documents and structures that define how an organization decides, enforces, and revises its security direction, and who is accountable for data.", "examContext": "Expect a direct match-the-document-type-to-its-purpose question, and a match-the-role question (owner vs. custodian vs. controller vs. processor)."}, {"type": "diagram", "heading": "The governance document hierarchy", "diagram": {"kind": "pyramid", "tiers": [{"label": "Policy", "note": "Management intent: why and what. Acceptable use, information security, change management."}, {"label": "Standard", "note": "A specific, mandatory requirement supporting a policy. Minimum password length."}, {"label": "Procedure", "note": "Exact step-by-step instructions. Onboarding, an incident playbook."}, {"label": "Guideline", "note": "Recommended, optional best practice.", "muted": true}], "top": "broadest", "bottom": "most specific"}}, {"type": "compare", "heading": "Mandatory or optional?", "columns": ["Policy", "Standard", "Procedure", "Guideline"], "rows": [{"label": "Mandatory", "values": ["Yes", "Yes", "Yes", "No"]}, {"label": "Level of detail", "values": ["High level", "Specific requirement", "Exact steps", "Advice"]}], "cue": ["\"Management intent\"", "\"Must\" with a number", "\"Step 1, step 2\"", "\"Should\" or \"recommended\""]}, {"type": "key_term", "term": "Governance structure", "definition": "How decisions get made: boards, committees, government bodies, and either one central authority or distributed authority.", "example": "A security steering committee of business unit leaders approves the annual security policy, while each region sets its own procedures."}, {"type": "callout", "variant": "info", "text": "Governance is shaped by external requirements (regulatory, legal, industry and regional) and needs ongoing **monitoring and revision** as those requirements and the business change."}, {"type": "compare", "heading": "Data roles", "columns": ["Responsibility"], "rows": [{"label": "Data owner", "values": ["Accountable for classification and protection; usually a senior business leader"]}, {"label": "Data controller", "values": ["Decides the purposes and means of processing personal data"]}, {"label": "Data processor", "values": ["Processes data for the controller, following its instructions"]}, {"label": "Data custodian / steward", "values": ["Day-to-day technical handling: backups, permissions"]}]}, {"type": "scenario", "prompt": "A document states that all passwords must be at least 14 characters. Which type of document is this?", "choices": [{"id": "a", "text": "Policy"}, {"id": "b", "text": "Standard"}, {"id": "c", "text": "Procedure"}, {"id": "d", "text": "Guideline"}], "answer": "b", "why": "A specific, mandatory requirement supporting a policy is a standard.", "trap": "It sounds like policy, but a policy states intent; specific numbers belong in a standard."}, {"type": "scenario", "prompt": "A payroll company runs payroll for its clients, following their instructions. Under privacy law, what is the payroll company?", "choices": [{"id": "a", "text": "Data owner"}, {"id": "b", "text": "Data controller"}, {"id": "c", "text": "Data processor"}, {"id": "d", "text": "Data subject"}], "answer": "c", "why": "It processes data on behalf of the controller, its client."}, {"type": "callout", "variant": "tip", "text": "Policy says why, standard says what exactly, procedure says how, guideline suggests. Owner is accountable; custodian does the daily work."}]'::jsonb where id = '3b8c3ac7-d5b3-4fbb-b2c7-d5d74d46cf0c';

-- The Risk Management Process
update lessons set content_blocks = '[{"text": "The Risk Management Process", "type": "title", "overview": "How organizations identify, measure, document, and decide what to do about risk, including the math behind quantitative risk analysis.", "examContext": "SLE/ARO/ALE calculations and matching a scenario to a risk management strategy (accept/transfer/avoid/mitigate/exempt) are both reliably tested."}, {"type": "compare", "heading": "Qualitative vs. quantitative", "columns": ["Qualitative", "Quantitative"], "rows": [{"label": "Expresses risk as", "values": ["Low, medium, high", "Dollar figures"]}, {"label": "Speed", "values": ["Fast", "Slower; needs data"]}, {"label": "Best for", "values": ["Quick prioritization", "Justifying spend on a control"]}], "intro": "Assessments can be ad hoc, recurring, one-time or continuous."}, {"type": "term_set", "heading": "The risk math", "terms": [{"term": "Asset value (AV)", "short": "What the asset is worth."}, {"term": "Exposure factor (EF)", "short": "Percentage of value lost in one incident."}, {"term": "SLE", "short": "Loss from one occurrence. **SLE = AV × EF**."}, {"term": "ARO", "short": "Expected occurrences per year. Once every 5 years is 0.2."}, {"term": "ALE", "short": "Expected yearly loss. **ALE = SLE × ARO**."}]}, {"type": "calc", "heading": "Calculate ALE", "kind": "ale", "intro": "A laptop fleet worth $300,000 loses 10% of its value in a typical theft incident, which happens about twice a year. Change the numbers to see the result move.", "defaults": {"assetValue": 300000, "exposureFactor": 10, "aro": 2}}, {"type": "scenario", "prompt": "A server worth $50,000 would lose 60% of its value in a flood, expected once every 10 years. What is the ALE?", "choices": [{"id": "a", "text": "$30,000"}, {"id": "b", "text": "$5,000"}, {"id": "c", "text": "$3,000"}, {"id": "d", "text": "$6,000"}], "answer": "c", "why": "SLE = $50,000 × 60% = $30,000. ARO = 0.1. ALE = $30,000 × 0.1 = **$3,000** a year.", "trap": "$30,000 is the SLE. Stopping there is the classic mistake."}, {"type": "compare", "heading": "Risk strategies", "columns": ["What it means", "Example"], "rows": [{"label": "Accept", "values": ["Do nothing; the control costs more than the risk", "Live with minor outage risk on a test server"]}, {"label": "Transfer", "values": ["Shift the financial impact", "Buy cyber insurance"]}, {"label": "Avoid", "values": ["Stop the risky activity", "Discontinue a feature that stores card numbers"]}, {"label": "Mitigate", "values": ["Reduce likelihood or impact", "Add MFA"]}, {"label": "Exception / exemption", "values": ["Formal, documented, time-bound approval to proceed", "Legacy app allowed for 90 days pending upgrade"]}]}, {"type": "term_set", "heading": "Tracking and tolerating risk", "terms": [{"term": "Risk register", "short": "Living record of threats, key risk indicators, owners and thresholds."}, {"term": "Risk appetite", "short": "The broad amount of risk the organization will pursue: expansionary, conservative or neutral."}, {"term": "Risk tolerance", "short": "The specific, measurable limit for one activity."}]}, {"type": "diagram", "heading": "BIA recovery metrics", "diagram": {"kind": "timeline", "event": "Outage", "before": {"label": "RPO", "note": "Maximum tolerable data loss, measured back to the last good backup."}, "after": [{"label": "RTO", "note": "How fast the system must be restored."}]}, "caption": "The BIA also tracks MTBF (how long between failures, higher is better) and MTTR (how long a repair takes, lower is better)."}, {"type": "scenario", "prompt": "A company buys a cyber insurance policy to cover breach costs. Which strategy is this?", "choices": [{"id": "a", "text": "Accept"}, {"id": "b", "text": "Transfer"}, {"id": "c", "text": "Avoid"}, {"id": "d", "text": "Mitigate"}], "answer": "b", "why": "Insurance shifts the financial impact to someone else."}, {"type": "callout", "variant": "tip", "text": "SLE = AV × EF, ALE = SLE × ARO. If a control costs less per year than the ALE it removes, it''s usually worth it."}]'::jsonb where id = '50186e4d-3368-4021-93f8-71ab370ecdd4';

-- Third-Party Risk Assessment and Management
update lessons set content_blocks = '[{"text": "Third-Party Risk Assessment and Management", "type": "title", "overview": "How organizations evaluate, select, formally agree with, and continue monitoring vendors and other third parties who touch their data or systems.", "examContext": "Expect a match-the-acronym question distinguishing SLA, MOA, MOU, MSA, SOW, NDA, and BPA."}, {"type": "term_set", "heading": "Assessing a vendor", "terms": [{"term": "Right-to-audit clause", "short": "Contractual right to audit or test the vendor''s security."}, {"term": "Evidence of internal audits", "short": "Ask for their audit results rather than taking their word."}, {"term": "Supply chain analysis", "short": "Assess the vendor''s own suppliers too."}, {"term": "Due diligence / conflict of interest", "short": "Research the vendor and check for conflicts before selecting."}, {"term": "Questionnaires", "short": "Structured security questions before and during the relationship."}]}, {"type": "compare", "heading": "Agreement types", "columns": ["Purpose"], "rows": [{"label": "SLA", "values": ["Measurable performance: uptime, response time"]}, {"label": "MOU", "values": ["Non-binding statement of intended cooperation"]}, {"label": "MOA", "values": ["More formal than an MOU, with defined responsibilities"]}, {"label": "MSA", "values": ["Overall terms governing future work orders"]}, {"label": "SOW / WO", "values": ["Scope, deliverables and timeline of one engagement"]}, {"label": "NDA", "values": ["Protects shared confidential information"]}, {"label": "BPA", "values": ["Formal business partnership, often with shared profit, loss or ownership"]}]}, {"type": "key_term", "term": "MSA and SOW together", "definition": "The MSA sets the overall terms once; each SOW defines one specific job under it.", "example": "A company signs one MSA with a consulting firm, then a separate SOW for a penetration test in March and another for a policy review in June."}, {"type": "callout", "variant": "info", "text": "**Rules of engagement** bound any vendor-performed security testing, and **vendor monitoring** continues for the whole relationship. Vetting once at the start isn''t enough."}, {"type": "scenario", "prompt": "A cloud provider contractually guarantees 99.95% uptime with service credits if it falls short. Which agreement covers this?", "choices": [{"id": "a", "text": "MOU"}, {"id": "b", "text": "SLA"}, {"id": "c", "text": "NDA"}, {"id": "d", "text": "BPA"}], "answer": "b", "why": "Measurable performance commitments belong in an SLA."}, {"type": "scenario", "prompt": "Two agencies want to document their intent to share threat intelligence, without creating legally binding obligations. Which document fits?", "choices": [{"id": "a", "text": "MSA"}, {"id": "b", "text": "MOU"}, {"id": "c", "text": "SOW"}, {"id": "d", "text": "SLA"}], "answer": "b", "why": "An MOU is a non-binding statement of intent.", "trap": "An MOA is more formal with defined responsibilities; non-binding points to MOU."}, {"type": "callout", "variant": "tip", "text": "MOU is a handshake, SLA is performance numbers, MSA is the umbrella, SOW is one job, NDA is secrets."}]'::jsonb where id = 'b40f6e51-894a-4340-b3dc-c7e2a7ece366';

-- Effective Security Compliance
update lessons set content_blocks = '[{"text": "Effective Security Compliance", "type": "title", "overview": "How organizations demonstrate they''re meeting legal and regulatory obligations, what happens when they don''t, and the privacy concepts driving many of those obligations.", "examContext": "Expect a scenario asking you to identify a consequence of non-compliance, and privacy questions distinguishing controller/processor/data subject."}, {"type": "compare", "heading": "Due diligence vs. due care", "columns": ["Due diligence", "Due care"], "rows": [{"label": "What it is", "values": ["Researching and identifying risk", "Acting on what you found"]}, {"label": "Question it answers", "values": ["Do we know our risks?", "Did we do something about them?"]}], "cue": ["\"Investigated\" or \"assessed\"", "\"Implemented\" or \"fixed\""]}, {"type": "term_set", "heading": "Compliance monitoring", "terms": [{"term": "Attestation / acknowledgement", "short": "Formal confirmation, often a signature, that policy is understood or a control exists."}, {"term": "Internal / external monitoring", "short": "Self-review / an outside party verifies."}, {"term": "Automation", "short": "Tools check configurations against benchmarks continuously."}, {"term": "Compliance reporting", "short": "Communicating status to leadership, regulators, customers or auditors."}]}, {"type": "term_set", "heading": "Consequences of non-compliance", "terms": [{"term": "Fines and sanctions", "short": "Imposed by a regulator."}, {"term": "Reputational damage", "short": "Lost customer and partner trust."}, {"term": "Loss of license", "short": "Can''t operate in an industry or jurisdiction."}, {"term": "Contractual impacts", "short": "Breach of a contract that required compliance."}]}, {"type": "term_set", "heading": "Privacy concepts", "terms": [{"term": "Data subject", "short": "The person the data is about."}, {"term": "Controller / processor", "short": "Decides why and how / processes on the controller''s behalf."}, {"term": "Data inventory", "short": "Knowing what personal data you hold and where."}, {"term": "Data retention", "short": "Defined limits on how long it''s kept."}, {"term": "Right to be forgotten", "short": "An individual''s right to have their personal data deleted."}], "intro": "Obligations vary by local, regional, national and global jurisdiction."}, {"type": "scenario", "prompt": "A company''s risk assessment identified unencrypted backups two years ago, but nothing was ever done about it. What did the company fail to show?", "choices": [{"id": "a", "text": "Due diligence"}, {"id": "b", "text": "Due care"}, {"id": "c", "text": "Attestation"}, {"id": "d", "text": "Data inventory"}], "answer": "b", "why": "They researched the risk (due diligence) but never acted on it (due care)."}, {"type": "scenario", "prompt": "A customer asks an online retailer to delete all personal data it holds about her. Which right is she exercising?", "choices": [{"id": "a", "text": "Right to audit"}, {"id": "b", "text": "Right to be forgotten"}, {"id": "c", "text": "Data sovereignty"}, {"id": "d", "text": "Attestation"}], "answer": "b", "why": "Deletion on request is the right to be forgotten."}, {"type": "callout", "variant": "tip", "text": "Due diligence finds the problem; due care fixes it. Finding without fixing is a classic exam scenario."}]'::jsonb where id = '9d249d35-dd8a-48e6-9547-029f3b8d7b3f';

-- Audits and Assessments
update lessons set content_blocks = '[{"text": "Audits and Assessments", "type": "title", "overview": "The formal mechanisms organizations use to verify their own security posture, from internal self-assessment to independent, authorized attack simulation.", "examContext": "Expect scenario questions distinguishing known/unknown/partially known environment penetration tests, and passive vs. active reconnaissance."}, {"type": "compare", "heading": "Internal vs. external audits", "columns": ["Internal", "External"], "rows": [{"label": "Performed by", "values": ["The organization''s own staff", "An outside party"]}, {"label": "Examples", "values": ["Self-assessments, audit committee reviews", "Regulatory exams, independent third-party audits"]}, {"label": "Strength", "values": ["Frequent and cheap", "Objective"]}], "intro": "**Attestation** is a formal statement, often from an auditor, that a control or compliance state exists."}, {"type": "compare", "heading": "Penetration test environments", "columns": ["Known (white box)", "Partially known (gray box)", "Unknown (black box)"], "rows": [{"label": "Tester starts with", "values": ["Full documentation", "Some information", "Nothing"]}, {"label": "Simulates", "values": ["A thorough insider review", "A user or partner", "A real external attacker"]}]}, {"type": "term_set", "heading": "Team colors", "terms": [{"term": "Red team", "short": "Attacks (offensive)."}, {"term": "Blue team", "short": "Defends and detects."}, {"term": "Purple team", "short": "Red and blue working together."}, {"term": "Physical test", "short": "Tests locks, badges and guards."}]}, {"type": "compare", "heading": "Passive vs. active reconnaissance", "columns": ["Passive", "Active"], "rows": [{"label": "Touches the target?", "values": ["No", "Yes"]}, {"label": "Examples", "values": ["OSINT, public records, DNS lookups via third parties", "Port scans, banner grabbing"]}, {"label": "Detection risk", "values": ["Low", "Higher"]}]}, {"type": "callout", "variant": "info", "text": "Every authorized engagement needs **rules of engagement**, formal **work authorization**, a defined **scope of work** and attention to **ethics** throughout."}, {"type": "scenario", "prompt": "Testers receive network diagrams, source code and admin credentials before starting. What kind of test is this?", "choices": [{"id": "a", "text": "Unknown environment"}, {"id": "b", "text": "Partially known environment"}, {"id": "c", "text": "Known environment"}, {"id": "d", "text": "Passive reconnaissance"}], "answer": "c", "why": "Full information up front is a known environment, also called white box."}, {"type": "scenario", "prompt": "Before touching any systems, a tester reviews the company''s job postings and employee social media to learn its technology stack. What is this?", "choices": [{"id": "a", "text": "Active reconnaissance"}, {"id": "b", "text": "Passive reconnaissance"}, {"id": "c", "text": "A physical test"}, {"id": "d", "text": "A blue team exercise"}], "answer": "b", "why": "Gathering information without interacting with the target is passive."}, {"type": "callout", "variant": "tip", "text": "White is known, gray is partial, black is unknown. Red attacks, blue defends, purple does both. Passive never touches the target."}]'::jsonb where id = 'b60c6988-b78d-4202-9e80-151f2defdaff';

-- Security Awareness Practices
update lessons set content_blocks = '[{"text": "Security Awareness Practices", "type": "title", "overview": "How organizations build and sustain a security-aware workforce, the single most consistently exploited weak point in any security program.", "examContext": "Expect scenario questions on recognizing anomalous behavior categories, and on why security awareness is a continuous cycle, not a one-time event."}, {"type": "diagram", "heading": "The awareness program cycle", "diagram": {"kind": "cycle", "steps": [{"label": "Development", "note": "Create relevant, current material."}, {"label": "Execution", "note": "Deliver initial and recurring training."}, {"label": "Reporting and monitoring", "note": "Track completion, phishing results and reports; improve."}], "center": "continuous"}, "caption": "One onboarding session is never enough. The exam rewards recurring training and ongoing phishing simulations."}, {"type": "key_term", "term": "Phishing campaigns", "definition": "Simulated phishing emails that test and reinforce recognition, paired with a clear way to report suspicious messages.", "example": "Quarterly simulations show click rates dropping from 18% to 4%, while reports to the security mailbox triple."}, {"type": "compare", "heading": "Anomalous behavior", "columns": ["Risky", "Unexpected", "Unintentional"], "rows": [{"label": "Meaning", "values": ["Raises risk without malice", "Outside the person''s normal pattern", "An accident with security consequences"]}, {"label": "Example", "values": ["Disabling the screen lock for convenience", "Logging in at 3 a.m. from a new country", "Emailing a file to the wrong person"]}]}, {"type": "term_set", "heading": "Training topics", "terms": [{"term": "Policy and handbook review", "short": "Know the rules and stay situationally aware."}, {"term": "Insider threat", "short": "Recognize warning signs from within."}, {"term": "Password management", "short": "Strong, unique passwords and a manager."}, {"term": "Removable media and cables", "short": "A common route for malware and data theft."}, {"term": "Social engineering", "short": "By email, phone and in person."}]}, {"type": "scenario", "prompt": "An employee who always works 9 to 5 from Chicago suddenly logs in at 2 a.m. from overseas. Which category of anomalous behavior is this?", "choices": [{"id": "a", "text": "Risky"}, {"id": "b", "text": "Unexpected"}, {"id": "c", "text": "Unintentional"}, {"id": "d", "text": "Normal"}], "answer": "b", "why": "Activity outside the person''s usual pattern is unexpected behavior."}, {"type": "scenario", "prompt": "Which approach best improves security awareness over time?", "choices": [{"id": "a", "text": "A detailed one-time onboarding course"}, {"id": "b", "text": "Recurring training with ongoing phishing simulations and tracked results"}, {"id": "c", "text": "An annual policy email"}, {"id": "d", "text": "Blocking all external email"}], "answer": "b", "why": "Awareness is a continuous cycle of development, execution and monitoring."}, {"type": "callout", "variant": "tip", "text": "Awareness is a cycle, never a one-time event. Risky is careless, unexpected is out of pattern, unintentional is an accident."}]'::jsonb where id = 'df190790-8add-4dff-8870-4c42b75dc471';

-- Domain 5 Recap
update lessons set content_blocks = '[{"text": "Domain 5 Recap: Security Program Management and Oversight", "type": "title", "overview": "A condensed pass over governance, risk management, third-party risk, compliance, audits, and security awareness.", "examContext": "This recap has no questions of its own; the Domain Checkpoint right after it draws fresh scenario questions from everything across all 6 lessons in this domain."}, {"type": "term_set", "heading": "Governance and roles", "terms": [{"term": "Policy, standard, procedure, guideline", "short": "Intent, mandatory requirement, exact steps, optional advice."}, {"term": "Owner / controller", "short": "Accountable / decides purpose and means."}, {"term": "Processor / custodian", "short": "Acts on the controller''s instructions / daily handling."}]}, {"type": "term_set", "heading": "Risk", "terms": [{"term": "SLE and ALE", "short": "SLE = AV × EF; ALE = SLE × ARO."}, {"term": "Strategies", "short": "Accept, transfer, avoid, mitigate, exception."}, {"term": "RTO / RPO", "short": "Maximum downtime / maximum data loss."}, {"term": "Risk register", "short": "Threats, indicators, owners and thresholds."}]}, {"type": "term_set", "heading": "Third parties and compliance", "terms": [{"term": "SLA / MOU / MSA / SOW / NDA", "short": "Performance / non-binding / umbrella terms / one job / confidentiality."}, {"term": "Due diligence / due care", "short": "Research the risk / act on it."}, {"term": "Non-compliance", "short": "Fines, reputation, loss of license, contract impact."}]}, {"type": "term_set", "heading": "Audits and awareness", "terms": [{"term": "White / gray / black box", "short": "Known / partially known / unknown."}, {"term": "Red / blue / purple", "short": "Attack / defend / together."}, {"term": "Passive / active recon", "short": "Doesn''t touch the target / does."}, {"term": "Awareness", "short": "Development, execution, monitoring: a continuous cycle."}]}, {"type": "scenario", "prompt": "An asset worth $100,000 has an exposure factor of 20% and an ARO of 0.5. What is the ALE?", "choices": [{"id": "a", "text": "$20,000"}, {"id": "b", "text": "$10,000"}, {"id": "c", "text": "$50,000"}, {"id": "d", "text": "$5,000"}], "answer": "b", "why": "SLE = $20,000; ALE = $20,000 × 0.5 = $10,000."}, {"type": "scenario", "prompt": "Which document is non-binding?", "choices": [{"id": "a", "text": "SLA"}, {"id": "b", "text": "MSA"}, {"id": "c", "text": "MOU"}, {"id": "d", "text": "NDA"}], "answer": "c", "why": "An MOU states intent without legal obligation."}, {"type": "scenario", "prompt": "Which team type combines attackers and defenders working together?", "choices": [{"id": "a", "text": "Red"}, {"id": "b", "text": "Blue"}, {"id": "c", "text": "Purple"}, {"id": "d", "text": "White"}], "answer": "c", "why": "Purple teams blend red and blue."}, {"type": "callout", "variant": "info", "text": "When you''re ready, head to the Domain Checkpoint: fresh scenarios from all six lessons in this domain."}]'::jsonb where id = '5affe219-8a10-4f19-97a1-5a401398a604';
